package com.groundmarkervariables.minify;

import java.math.BigInteger;
import java.util.Arrays;

// Writes bytes as one big number in ~3200 Western-looking letters and symbols (~11.7 bits per char).
// None are ASCII, emoji, accents, spaces or right-to-left, and normalizing can't change them. Never
// change: exports must keep importing.
final class GmvAlphabet
{
	// First/last char pairs.
	private static final String RANGES = "¡§©©¬¬®®°±¶·¿¿ÆÆÐÐ"
		+ "×ØÞßææðð÷øþþĐđĦħıı"
		+ "ĸĸŁłŊŋŒœŦŧƀƟƢƮƱǃǝǝ"
		+ "ǤǥǶǷȜȝȠȠȢȥɐʭ͵͵ΑΡΣΩ"
		+ "αωϗϯϳϳ϶϶ЂЂЄІЈЋЏИКи"
		+ "кяђђєіјћџѵѸ҂ҊӀӃӎӔӕ"
		+ "ӘәӠӡӨөԀԏԱՖՙ՟աֆ։֊ႠჅ"
		+ "აჸ჻჻ᎠᏴᐁᙶᚁ᚜ᚠᛰ℄℄℈℈℔℔"
		+ "℗℘℞℟℣℣℥℥℧℧℩℩℮℮ℲℲ℺℺"
		+ "⅁⅄⅊⅋←↓↜↨↫↭↯⇌⇐∃∅∈∊∋"
		+ "∍∣∥∥∧∫∮∮∱≀≂≃≅≆≈≈≊≟"
		+ "≡≡≣≬≲≳≶≷≺≿⊂⊃⊆⊇⊊⊫⊰⋟"
		+ "⋤⋩⋮⌙⌜⌧⌫⏎␀␦⑀⑊─▩▬▵▷▿"
		+ "◁◺◿◿✁✁✃✄✆✇✎✎✐✑✓✓✕✕"
		+ "✗✜✞✠✢✧✩✲✵❃❅❆❈❋❍❍❏❒"
		+ "❖❖❘❞❡❢❥➔➘➠➢➯➱➾⟰⤳⤶⨋"
		+ "⨍⩳⩷⫛⫝⫿";

	private static final char[] CHARS = chars();
	private static final BigInteger BASE = BigInteger.valueOf(CHARS.length);
	// Char -> its digit, or -1.
	private static final int[] INDEX = new int[Character.MAX_VALUE + 1];

	static
	{
		Arrays.fill(INDEX, -1);
		for (int i = 0; i < CHARS.length; i++)
		{
			INDEX[CHARS[i]] = i;
		}
	}

	private GmvAlphabet()
	{
	}

	private static char[] chars()
	{
		StringBuilder chars = new StringBuilder();
		for (int i = 0; i < RANGES.length(); i += 2)
		{
			for (char c = RANGES.charAt(i); c <= RANGES.charAt(i + 1); c++)
			{
				chars.append(c);
			}
		}
		return chars.toString().toCharArray();
	}

	static String encode(byte[] data)
	{
		// A leading 1 keeps leading zero bytes.
		byte[] marked = new byte[data.length + 1];
		marked[0] = 1;
		System.arraycopy(data, 0, marked, 1, data.length);

		StringBuilder digits = new StringBuilder();
		BigInteger value = new BigInteger(1, marked);
		while (value.signum() > 0)
		{
			BigInteger[] divided = value.divideAndRemainder(BASE);
			digits.append(CHARS[divided[1].intValue()]);
			value = divided[0];
		}
		return digits.reverse().toString();
	}

	// Throws IllegalArgumentException if text wasn't made by encode().
	static byte[] decode(String text)
	{
		BigInteger value = BigInteger.ZERO;
		for (int i = 0; i < text.length(); i++)
		{
			int digit = INDEX[text.charAt(i)];
			if (digit < 0 || i == 0 && digit == 0)
			{
				throw new IllegalArgumentException("Not a digit at " + i);
			}
			value = value.multiply(BASE).add(BigInteger.valueOf(digit));
		}

		byte[] marked = value.toByteArray();
		if (marked.length == 0 || marked[0] != 1)
		{
			throw new IllegalArgumentException("Missing marker byte");
		}
		return Arrays.copyOfRange(marked, 1, marked.length);
	}
}

package com.groundmarkervariables.minify;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.List;
import java.util.zip.DataFormatException;
import java.util.zip.Deflater;
import java.util.zip.Inflater;

// Deflate primed with a versioned dictionary of our label syntax, for exports and party sharing.
public final class MarkerCompression
{
	public static final int VERSION = 1;
	// Version N uses entry N - 1. Never edit a dictionary; add a new version.
	private static final List<byte[]> DICTIONARIES = List.of(
		dictionary("dictionary-1.txt", "81eab1acbd9c88a475d263b11e4a851d09d61bcf1c0fafaa82fef37debfcbd44"));

	private MarkerCompression()
	{
	}

	// With the current VERSION.
	public static byte[] compress(String text)
	{
		Deflater deflater = new Deflater(Deflater.BEST_COMPRESSION, true);
		deflater.setDictionary(DICTIONARIES.get(VERSION - 1));
		deflater.setInput(text.getBytes(StandardCharsets.UTF_8));
		deflater.finish();

		ByteArrayOutputStream out = new ByteArrayOutputStream();
		byte[] buffer = new byte[1024];
		while (!deflater.finished())
		{
			out.write(buffer, 0, deflater.deflate(buffer));
		}
		deflater.end();
		return out.toByteArray();
	}

	// Throws IllegalArgumentException if data is damaged.
	public static String decompress(byte[] data, int version) throws NewerFormatException
	{
		if (version > DICTIONARIES.size())
		{
			throw new NewerFormatException();
		}
		if (version < 1)
		{
			throw new IllegalArgumentException("No version " + version);
		}

		Inflater inflater = new Inflater(true);
		inflater.setDictionary(DICTIONARIES.get(version - 1));
		inflater.setInput(data);

		ByteArrayOutputStream out = new ByteArrayOutputStream();
		byte[] buffer = new byte[1024];
		try
		{
			while (!inflater.finished())
			{
				int count = inflater.inflate(buffer);
				if (count == 0 && inflater.needsInput())
				{
					throw new IllegalArgumentException("Truncated");
				}
				out.write(buffer, 0, count);
			}
			if (inflater.getRemaining() > 0)
			{
				throw new IllegalArgumentException("Trailing data");
			}
		}
		catch (DataFormatException e)
		{
			throw new IllegalArgumentException("Damaged", e);
		}
		finally
		{
			inflater.end();
		}
		return out.toString(StandardCharsets.UTF_8);
	}

	// Loads a dictionary-N.txt (format in its header) and checks it wasn't edited.
	private static byte[] dictionary(String file, String sha256)
	{
		try (InputStream in = MarkerCompression.class.getResourceAsStream(file))
		{
			if (in == null)
			{
				throw new IllegalStateException("Missing " + file);
			}

			StringBuilder dictionary = new StringBuilder();
			for (String line : new String(in.readAllBytes(), StandardCharsets.UTF_8).split("\n"))
			{
				line = line.strip();
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				// '·' at either end is a space.
				line = line.startsWith("·") ? " " + line.substring(1) : line;
				line = line.endsWith("·") ? line.substring(0, line.length() - 1) + " " : line;
				dictionary.append(line);
			}

			byte[] bytes = dictionary.toString().getBytes(StandardCharsets.UTF_8);
			String hash = sha256(bytes);
			if (!hash.equals(sha256))
			{
				throw new IllegalStateException(file + " was edited: its SHA-256 is " + hash);
			}
			return bytes;
		}
		catch (IOException e)
		{
			throw new IllegalStateException("Couldn't load " + file, e);
		}
	}

	private static String sha256(byte[] bytes)
	{
		try
		{
			StringBuilder hex = new StringBuilder();
			for (byte b : MessageDigest.getInstance("SHA-256").digest(bytes))
			{
				hex.append(String.format("%02x", b));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			throw new IllegalStateException(e);
		}
	}
}

package com.groundmarkervariables.minify;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonSyntaxException;
import com.groundmarkervariables.GroundMarkerPointData;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

// Exports markers as core's JSON, but a label with variables becomes "gmv":"<version>~<compressed>".
// Core ignores that field, so it still imports the tile, without the label.
public class MarkerMinifier
{
	private static final String FIELD = "gmv";
	private static final Pattern GMV = Pattern.compile("(\\d+)~(.+)");

	private final Gson gson;

	@Inject
	private MarkerMinifier(Gson gson)
	{
		this.gson = gson;
	}

	public String export(List<GroundMarkerPointData> points)
	{
		JsonArray array = gson.toJsonTree(points).getAsJsonArray();
		for (int i = 0; i < points.size(); i++)
		{
			String label = points.get(i).getLabel();
			if (label != null && label.contains("{"))
			{
				JsonObject marker = array.get(i).getAsJsonObject();
				marker.remove("label");
				marker.addProperty(FIELD, MarkerCompression.VERSION + "~" + GmvAlphabet.encode(MarkerCompression.compress(label)));
			}
		}
		return gson.toJson(array);
	}

	// Throws JsonSyntaxException if text isn't an array of markers, IllegalArgumentException if a gmv
	// label is damaged.
	public List<GroundMarkerPointData> parse(String text) throws NewerFormatException
	{
		JsonElement json = gson.fromJson(text, JsonElement.class);
		if (json == null || json.isJsonNull())
		{
			return List.of();
		}
		if (!json.isJsonArray())
		{
			throw new JsonSyntaxException("Not an array of markers");
		}

		List<GroundMarkerPointData> points = new ArrayList<>();
		for (JsonElement element : json.getAsJsonArray())
		{
			GroundMarkerPointData point = gson.fromJson(element, GroundMarkerPointData.class);
			if (point == null)
			{
				continue;
			}

			JsonElement gmv = element.getAsJsonObject().get(FIELD);
			if (gmv != null && gmv.isJsonPrimitive())
			{
				point = new GroundMarkerPointData(point.getRegionId(), point.getRegionX(), point.getRegionY(), point.getZ(),
					point.getColor(), label(gmv.getAsString()));
			}
			points.add(point);
		}
		return points;
	}

	private static String label(String gmv) throws NewerFormatException
	{
		Matcher matcher = GMV.matcher(gmv);
		if (!matcher.matches())
		{
			throw new IllegalArgumentException("Damaged gmv label");
		}
		return MarkerCompression.decompress(GmvAlphabet.decode(matcher.group(2)), Integer.parseInt(matcher.group(1)));
	}
}

