// "Party -> Ground Markers" submenu beneath "Export -> Ground Markers": "Share to Party" sends
// every currently loaded marker; recipients get "Import ... from <user>" for PendingPartyShare.TTL.
@Slf4j
@Singleton
public class GroundMarkerPartySharingManager
{
	private static final int WIDGET_FIXED = InterfaceID.Orbs.WORLDMAP;
	private static final int WIDGET_RESIZABLE = InterfaceID.OrbsNomap.WORLDMAP;

	private static final String TARGET = ColorUtil.wrapWithColorTag("Ground Markers", JagexColors.MENU_TARGET);

	private static final Duration BADGE_FULL_OPACITY_DURATION = Duration.ofSeconds(2);
	private static final Duration BADGE_FADE_DURATION = Duration.ofSeconds(3);
	private static final Duration BADGE_VISIBLE_DURATION = BADGE_FULL_OPACITY_DURATION.plus(BADGE_FADE_DURATION);

	// Keyed by sender -- one pending share per sender, replaced (not merged) by their next one.
	private final Map<Long, PendingPartyShare> pendingShares = new ConcurrentHashMap<>();

	private volatile Instant lastReceivedAt;
	private ScheduledFuture<?> badgeClearTask;

	private final Client client;
	private final ChatboxPanelManager chatboxPanelManager;
	private final ChatMessageManager chatMessageManager;
	private final EventBus eventBus;
	private final ScheduledExecutorService executor;
	private final ImportPreviewManager importPreviewManager;
	private final GroundMarkerVariablesSharingManager sharingManager;
	private final PartyService partyService;
	private final WSClient wsClient;
	private final Gson gson;

	@Inject
	private GroundMarkerPartySharingManager(Client client, ChatboxPanelManager chatboxPanelManager, ChatMessageManager chatMessageManager,
		EventBus eventBus, ScheduledExecutorService executor, ImportPreviewManager importPreviewManager,
		GroundMarkerVariablesSharingManager sharingManager, PartyService partyService, WSClient wsClient, Gson gson)
	{
		this.gson = gson;
		this.client = client;
		this.chatboxPanelManager = chatboxPanelManager;
		this.chatMessageManager = chatMessageManager;
		this.eventBus = eventBus;
		this.executor = executor;
		this.importPreviewManager = importPreviewManager;
		this.sharingManager = sharingManager;
		this.partyService = partyService;
		this.wsClient = wsClient;
	}

	public void startUp()
	{
		eventBus.register(this);
		registerMessage(GMVCompressedMarkerShare.class);
		registerMessage(GMVGroundMarkerPartyShare.class);
	}

	private void registerMessage(Class<? extends PartyMemberMessage> message)
	{
		try
		{
			wsClient.registerMessage(message);
		}
		catch (IllegalArgumentException e)
		{
			log.warn("Party marker sharing unavailable due to a message type collision with another plugin", e);
		}
	}

	private void unregisterMessage(Class<? extends PartyMemberMessage> message)
	{
		try
		{
			wsClient.unregisterMessage(message);
		}
		catch (IllegalArgumentException e)
		{
			// Never registered successfully.
		}
	}

	public void shutDown()
	{
		eventBus.unregister(this);
		if (badgeClearTask != null)
		{
			badgeClearTask.cancel(false);
		}

		unregisterMessage(GMVCompressedMarkerShare.class);
		unregisterMessage(GMVGroundMarkerPartyShare.class);

		pendingShares.clear();
		lastReceivedAt = null;
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (client.isWidgetSelected() || event.getType() != MenuAction.CC_OP.getId())
		{
			return;
		}

		int widgetId = event.getActionParam1();
		if (widgetId != WIDGET_FIXED && widgetId != WIDGET_RESIZABLE)
		{
			return;
		}

		if (!partyService.isInParty())
		{
			return;
		}

		for (MenuEntry entry : client.getMenuEntries())
		{
			if ("Party".equals(entry.getOption()) && TARGET.equals(entry.getTarget()))
			{
				return;
			}
		}

		Menu submenu = client.createMenuEntry(-2)
			.setOption("Party")
			.setTarget(TARGET)
			.setType(MenuAction.RUNELITE)
			.createSubMenu();

		submenu.createMenuEntry(-1)
			.setOption("Share to Party")
			.setType(MenuAction.RUNELITE)
			.onClick(e -> promptShare());

		List<PendingPartyShare> pending = new ArrayList<>(pendingShares.values());
		pending.sort(Comparator.comparing((PendingPartyShare p) -> p.receivedAt).reversed());
		for (PendingPartyShare share : pending)
		{
			submenu.createMenuEntry(-1)
				.setOption("Import " + share.markers.size() + " markers from " + share.senderName)
				.setType(MenuAction.RUNELITE)
				.onClick(e -> promptImport(share));
		}
	}

	private void promptShare()
	{
		List<GroundMarkerPointData> activePoints = sharingManager.activePoints();
		if (activePoints.isEmpty())
		{
			sendChatMessage("You have no ground markers to share.");
			return;
		}

		chatboxPanelManager.openTextMenuInput("Are you sure you want to share " + activePoints.size() + " ground markers with your party?")
			.option("Yes", () -> share(activePoints))
			.option("No", Runnables.doNothing())
			.build();
	}

	private void share(List<GroundMarkerPointData> points)
	{
		byte[] compressed = MarkerCompression.compress(gson.toJson(points));
		partyService.send(new GMVCompressedMarkerShare(MarkerCompression.VERSION, Base64.getEncoder().withoutPadding().encodeToString(compressed)));
		sendChatMessage(points.size() + " ground markers were shared with your party.");
	}

	@Subscribe
	public void onGMVCompressedMarkerShare(GMVCompressedMarkerShare share)
	{
		if (isOwn(share))
		{
			return;
		}

		List<GroundMarkerPointData> points;
		try
		{
			String json = MarkerCompression.decompress(Base64.getDecoder().decode(share.getData()), share.getVersion());
			points = gson.fromJson(json, new TypeToken<List<GroundMarkerPointData>>(){}.getType());
		}
		catch (NewerFormatException e)
		{
			sendChatMessage(senderName(share) + " shared ground markers from a newer version of Ground Marker Variables. Update the plugin to import them.");
			return;
		}
		catch (IllegalArgumentException | JsonSyntaxException e)
		{
			log.debug("Damaged party marker share", e);
			return;
		}
		addPending(share, points);
	}

	@Subscribe
	public void onGMVGroundMarkerPartyShare(GMVGroundMarkerPartyShare share)
	{
		if (isOwn(share))
		{
			return;
		}

		List<GroundMarkerPointData> points = new ArrayList<>();
		for (GMVGroundMarkerPartyShare.SharedMarker marker : share.getMarkers())
		{
			WorldPoint point = marker.getPoint();
			Color color = marker.getColorRgb() == null ? null : new Color(marker.getColorRgb(), true);
			points.add(new GroundMarkerPointData(point.getRegionID(), point.getRegionX(), point.getRegionY(), point.getPlane(), color, marker.getLabel()));
		}
		addPending(share, points);
	}

	private boolean isOwn(PartyMemberMessage message)
	{
		PartyMember local = partyService.getLocalMember();
		return local != null && message.getMemberId() == local.getMemberId();
	}

	private String senderName(PartyMemberMessage message)
	{
		PartyMember sender = partyService.getMemberById(message.getMemberId());
		return sender != null ? sender.getDisplayName() : "Unknown";
	}

	// Replaces any pending share from the same sender. The scheduled removal is keyed to this exact
	// instance, so a stale timer from a replaced share can never remove the one that replaced it.
	private void addPending(PartyMemberMessage share, List<GroundMarkerPointData> points)
	{
		if (points == null || points.isEmpty())
		{
			return;
		}

		PendingPartyShare pending = new PendingPartyShare(share.getMemberId(), senderName(share), points, Instant.now());
		pendingShares.put(share.getMemberId(), pending);
		executor.schedule(() -> pendingShares.remove(pending.senderMemberId, pending), PendingPartyShare.TTL.getSeconds(), TimeUnit.SECONDS);

		showBadge();
	}

	private void promptImport(PendingPartyShare pending)
	{
		List<GroundMarkerPointData> points = pending.markers;
		List<GroundMarkerPointData> nonOverlapping = sharingManager.nonOverlapping(points);
		importPreviewManager.show(nonOverlapping);
		String count = GroundMarkerVariablesSharingManager.countWithOverlap(points.size(), nonOverlapping.size());
		chatboxPanelManager.openTextMenuInput(
				"Are you sure you want to import " + count + " ground markers<br>from " + pending.senderName + "?")
			.option("Yes", () -> doImport(pending, nonOverlapping))
			.option("No", Runnables.doNothing())
			.onClose(importPreviewManager::clear)
			.build();
	}

	private void doImport(PendingPartyShare pending, List<GroundMarkerPointData> points)
	{
		sharingManager.importGroundMarkers(points);
		sendChatMessage(points.size() + " ground markers were imported from " + pending.senderName + ".");
		pendingShares.remove(pending.senderMemberId, pending);
	}

	// Cancels any still-pending clear from an earlier badge before scheduling this one, so an
	// old timer can never null out a newer receipt.
	private void showBadge()
	{
		lastReceivedAt = Instant.now();
		if (badgeClearTask != null)
		{
			badgeClearTask.cancel(false);
		}
		badgeClearTask = executor.schedule(() -> lastReceivedAt = null, BADGE_VISIBLE_DURATION.toMillis(), TimeUnit.MILLISECONDS);
	}

	// 100% for the first 2s, linearly down to 0% over the next 3s, null (hidden) after that.
	float badgeOpacity(Instant now)
	{
		Instant receivedAt = lastReceivedAt;
		if (receivedAt == null)
		{
			return 0f;
		}

		Duration age = Duration.between(receivedAt, now);
		if (age.compareTo(BADGE_FULL_OPACITY_DURATION) <= 0)
		{
			return 1f;
		}

		Duration intoFade = age.minus(BADGE_FULL_OPACITY_DURATION);
		return 1f - (float) intoFade.toMillis() / BADGE_FADE_DURATION.toMillis();
	}

	private void sendChatMessage(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(message)
			.build());
	}
}

package com.groundmarkervariables.party;

import java.awt.AlphaComposite;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.time.Instant;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

// Badge over the World Map orb's top-left corner, shown when GroundMarkerPartySharingManager
// receives a party-shared marker set. Opacity comes from its badgeOpacity(now).
public class PartyNotificationOverlay extends Overlay
{
	private static final int SPRITE_ID = 937;
	private static final int WIDTH = 5;
	private static final int HEIGHT = 16;

	private final Client client;
	private final GroundMarkerPartySharingManager partySharingManager;
	private final SpriteManager spriteManager;

	@Inject
	private PartyNotificationOverlay(Client client, GroundMarkerPartySharingManager partySharingManager, SpriteManager spriteManager)
	{
		this.client = client;
		this.partySharingManager = partySharingManager;
		this.spriteManager = spriteManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		float opacity = partySharingManager.badgeOpacity(Instant.now());
		if (opacity <= 0f)
		{
			return null;
		}

		Widget worldMapOrb = client.getWidget(InterfaceID.Orbs.WORLDMAP);
		if (worldMapOrb == null || worldMapOrb.isHidden())
		{
			worldMapOrb = client.getWidget(InterfaceID.OrbsNomap.WORLDMAP);
		}
		if (worldMapOrb == null || worldMapOrb.isHidden())
		{
			return null;
		}

		Rectangle bounds = worldMapOrb.getBounds();
		if (bounds.getX() <= 0)
		{
			return null;
		}

		BufferedImage sprite = spriteManager.getSprite(SPRITE_ID, 0);
		if (sprite == null)
		{
			return null;
		}

		// Centered on the corner, not flush inside/outside it.
		int x = bounds.x - WIDTH / 2;
		int y = bounds.y - HEIGHT / 2;

		Composite originalComposite = graphics.getComposite();
		if (opacity < 1f)
		{
			graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, opacity));
		}
		graphics.drawImage(sprite, x, y, WIDTH, HEIGHT, null);
		graphics.setComposite(originalComposite);

		return null;
	}
}

package com.groundmarkervariables.party;

import com.groundmarkervariables.GroundMarkerPointData;
import java.time.Duration;
import java.time.Instant;
import java.util.List;

// One sender's pending shared marker set -- removed by its own scheduled task after TTL (see
// GroundMarkerPartySharingManager), not persisted or rendered until actually imported.
class PendingPartyShare
{
	static final Duration TTL = Duration.ofSeconds(120);

	final long senderMemberId;
	final String senderName;
	final List<GroundMarkerPointData> markers;
	final Instant receivedAt;

	PendingPartyShare(long senderMemberId, String senderName, List<GroundMarkerPointData> markers, Instant receivedAt)
	{
		this.senderMemberId = senderMemberId;
		this.senderName = senderName;
		this.markers = markers;
		this.receivedAt = receivedAt;
	}
}

package com.groundmarkervariables.party;

import com.groundmarkervariables.CachedMarker;

import java.time.Duration;
import java.time.Instant;

// One temp-cached tile shared by a party member's ping — not persisted, just displayed for a
// while. Mirrors TranslatedMarker's style (a small holder around a CachedMarker).
public class PingedTile
{
	private static final Duration FULL_OPACITY_DURATION = Duration.ofSeconds(5);
	private static final Duration FADE_DURATION = Duration.ofSeconds(20);
	static final Duration TTL = FULL_OPACITY_DURATION.plus(FADE_DURATION).plusSeconds(5);

	public final CachedMarker marker;
	final long senderMemberId;
	// Snapshotted at receipt -- the sender may leave the party before this entry expires.
	final String senderName;
	final Instant receivedAt;

	PingedTile(CachedMarker marker, long senderMemberId, String senderName, Instant receivedAt)
	{
		this.marker = marker;
		this.senderMemberId = senderMemberId;
		this.senderName = senderName;
		this.receivedAt = receivedAt;
	}

	// 100% for the first 5s, linearly down to 0% over the next 20s, then 0% until expiry.
	public float opacity(Instant now)
	{
		Duration age = Duration.between(receivedAt, now);
		if (age.compareTo(FULL_OPACITY_DURATION) <= 0)
		{
			return 1f;
		}

		Duration intoFade = age.minus(FULL_OPACITY_DURATION);
		if (intoFade.compareTo(FADE_DURATION) >= 0)
		{
			return 0f;
		}

		return 1f - (float) intoFade.toMillis() / FADE_DURATION.toMillis();
	}
}

package com.groundmarkervariables.party;

import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import com.groundmarkervariables.CachedMarker;
import com.groundmarkervariables.GroundMarkerPointData;
import com.groundmarkervariables.GroundMarkerVariablesConfig;
import com.groundmarkervariables.GroundMarkerVariablesPlugin;
import com.groundmarkervariables.MarkerStorage;
import com.groundmarkervariables.variables.LabelResolver;
import com.groundmarkervariables.variables.meta.MetaVariableResolver;
import java.awt.Color;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.WorldViewLoaded;
import net.runelite.api.events.WorldViewUnloaded;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.events.PartyChanged;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.plugins.party.messages.TilePing;

// Shares a marked tile with the party when you ping it, and displays tiles shared by others as
// a temporary, fading marker with its own "Save"/"Hide" right-click options. See PINGEDTILE.md.
@Slf4j
@Singleton
public class PingedTileManager
{
	// Arrives on WSClient's own thread, not the client/AWT thread render()/menus run on.
	private final Map<WorldPoint, PingedTile> pingedTiles = new ConcurrentHashMap<>();

	// Mirrors GroundMarkerVariablesPlugin's markersByWorldView, rebuilt by retranslate().
	private final Map<WorldView, List<TranslatedPingedTile>> translatedByWorldView = new ConcurrentHashMap<>();

	// Send-side debounce, presence-only, self-evicting after 2s.
	private final Cache<WorldPoint, Boolean> recentlySent = CacheBuilder.newBuilder()
		.expireAfterWrite(2, TimeUnit.SECONDS)
		.build();

	// Senders with one hide so far this session -- a second hide blocks them.
	private final Set<Long> hiddenOnceSenderIds = ConcurrentHashMap.newKeySet();
	private final Set<Long> blockedSenderIds = ConcurrentHashMap.newKeySet();

	private final Client client;
	private final ClientThread clientThread;
	private final EventBus eventBus;
	private final ScheduledExecutorService executor;
	private final GroundMarkerVariablesConfig config;
	private final GroundMarkerVariablesPlugin plugin;
	private final MarkerStorage markerStorage;
	private final LabelResolver labelResolver;
	private final MetaVariableResolver metaVariableResolver;
	private final PartyService partyService;
	private final WSClient wsClient;
	private final ChatMessageManager chatMessageManager;

	@Inject
	private PingedTileManager(Client client, ClientThread clientThread, EventBus eventBus, ScheduledExecutorService executor,
		GroundMarkerVariablesConfig config, GroundMarkerVariablesPlugin plugin, MarkerStorage markerStorage, LabelResolver labelResolver,
		MetaVariableResolver metaVariableResolver, PartyService partyService, WSClient wsClient, ChatMessageManager chatMessageManager)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.eventBus = eventBus;
		this.executor = executor;
		this.config = config;
		this.plugin = plugin;
		this.markerStorage = markerStorage;
		this.labelResolver = labelResolver;
		this.metaVariableResolver = metaVariableResolver;
		this.partyService = partyService;
		this.wsClient = wsClient;
		this.chatMessageManager = chatMessageManager;
	}

	public void startUp()
	{
		eventBus.register(this);

		try
		{
			wsClient.registerMessage(TilePing.class);
			wsClient.registerMessage(GMVPingedTileShare.class);
		}
		catch (IllegalArgumentException e)
		{
			log.warn("Pinged tile sharing unavailable due to a message type collision with another plugin", e);
		}
	}

	public void shutDown()
	{
		eventBus.unregister(this);

		try
		{
			wsClient.unregisterMessage(GMVPingedTileShare.class);
		}
		catch (IllegalArgumentException e)
		{
			// Never registered successfully.
		}

		pingedTiles.clear();
		translatedByWorldView.clear();
		hiddenOnceSenderIds.clear();
		blockedSenderIds.clear();
	}

	// Blocks are scoped to the current party session.
	@Subscribe
	public void onPartyChanged(PartyChanged event)
	{
		if (event.getPartyId() == null)
		{
			hiddenOnceSenderIds.clear();
			blockedSenderIds.clear();
		}
	}

	// Reacts only to our own ping (the relay echoes TilePing back to the sender too) -- shares
	// the tile there if we have one marked.
	@Subscribe
	public void onTilePing(TilePing event)
	{
		if (!config.sendPingedTiles())
		{
			return;
		}

		PartyMember local = partyService.getLocalMember();
		if (local == null || event.getMemberId() != local.getMemberId())
		{
			return;
		}

		WorldPoint point = event.getPoint();
		if (recentlySent.getIfPresent(point) != null)
		{
			return;
		}

		GroundMarkerPointData existing = markerStorage.findStoredPoint(point);
		if (existing == null)
		{
			return;
		}

		recentlySent.put(point, Boolean.TRUE);
		Integer rgb = existing.getColor() == null ? null : existing.getColor().getRGB();
		partyService.send(new GMVPingedTileShare(point, rgb, existing.getLabel()));
	}

	// Displays a tile shared by another party member, unless we already have it marked.
	@Subscribe
	public void onGMVPingedTileShare(GMVPingedTileShare share)
	{
		if (!config.showPingedTiles())
		{
			return;
		}

		if (blockedSenderIds.contains(share.getMemberId()))
		{
			return;
		}

		WorldPoint point = share.getPoint();
		if (markerStorage.findStoredPoint(point) != null)
		{
			return;
		}

		PartyMember sender = partyService.getMemberById(share.getMemberId());
		String senderName = sender != null ? sender.getDisplayName() : "Unknown";
		Color color = share.getColorRgb() == null ? null : new Color(share.getColorRgb(), true);

		// Resolving the label needs the client thread; this handler runs on WSClient's own.
		clientThread.invoke(() ->
		{
			GroundMarkerPointData transientPoint = new GroundMarkerPointData(
				point.getRegionID(), point.getRegionX(), point.getRegionY(), point.getPlane(), color, share.getLabel());
			CachedMarker marker = new CachedMarker(transientPoint, labelResolver, metaVariableResolver);
			PingedTile pinged = new PingedTile(marker, share.getMemberId(), senderName, Instant.now());
			pingedTiles.put(point, pinged);
			retranslate();

			// Keyed to this exact instance, so a stale timer can never remove a later ping that
			// landed on the same tile.
			executor.schedule(() -> clientThread.invoke(() ->
			{
				if (pingedTiles.remove(point, pinged))
				{
					retranslate();
				}
			}), PingedTile.TTL.getSeconds(), TimeUnit.SECONDS);
		});
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		pingedTiles.values().forEach(tile -> tile.marker.refresh(labelResolver, metaVariableResolver));
	}

	// Same two hooks GroundMarkerVariablesPlugin uses for its own markersByWorldView.
	@Subscribe
	public void onWorldViewLoaded(WorldViewLoaded event)
	{
		retranslate();
	}

	@Subscribe
	public void onWorldViewUnloaded(WorldViewUnloaded event)
	{
		retranslate();
	}

	// Mirrors GroundMarkerVariablesPlugin#translateWorldView. Drops any tile that no longer
	// resolves anywhere, instead of just skipping it.
	private void retranslate()
	{
		Map<WorldView, List<TranslatedPingedTile>> rebuilt = new ConcurrentHashMap<>();
		Set<WorldPoint> resolved = new HashSet<>();

		for (WorldView wv : plugin.getTrackedWorldViews())
		{
			List<TranslatedPingedTile> translated = new ArrayList<>();
			for (PingedTile tile : pingedTiles.values())
			{
				GroundMarkerPointData source = tile.marker.source;
				WorldPoint point = WorldPoint.fromRegion(source.getRegionId(), source.getRegionX(), source.getRegionY(), source.getZ());
				for (WorldPoint wp : WorldPoint.toLocalInstance(wv, point))
				{
					translated.add(new TranslatedPingedTile(wp, tile));
					resolved.add(point);
				}
			}
			rebuilt.put(wv, translated);
		}

		translatedByWorldView.clear();
		translatedByWorldView.putAll(rebuilt);
		pingedTiles.keySet().removeIf(point -> !resolved.contains(point));
	}

	// Independent of GroundMarkerVariablesPlugin's own shift-gated Mark/Unmark/Label/Color --
	// Save/Hide apply to a temp-cached ping, not a persisted marker, and aren't shift-gated.
	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		MenuAction menuAction = event.getMenuEntry().getType();
		if (menuAction != MenuAction.WALK && menuAction != MenuAction.SET_HEADING)
		{
			return;
		}

		WorldView wv = client.getWorldView(event.getMenuEntry().getWorldViewId());
		if (wv == null)
		{
			return;
		}

		Tile selectedSceneTile = wv.getSelectedSceneTile();
		if (selectedSceneTile == null)
		{
			return;
		}

		WorldPoint worldPoint = WorldPoint.fromLocalInstance(client, selectedSceneTile.getLocalLocation());
		PingedTile pinged = pingedTiles.get(worldPoint);
		if (pinged == null)
		{
			return;
		}

		client.createMenuEntry(-1)
			.setOption("Save " + pinged.senderName + "'s")
			.setTarget("Tile")
			.setType(MenuAction.RUNELITE)
			.onClick(e -> save(worldPoint, pinged));

		client.createMenuEntry(-2)
			.setOption("Hide " + pinged.senderName + "'s")
			.setTarget("Tile")
			.setType(MenuAction.RUNELITE)
			.onClick(e -> hide(worldPoint, pinged));
	}

	// A second hide from the same sender blocks them for the rest of this party session.
	private void hide(WorldPoint worldPoint, PingedTile pinged)
	{
		pingedTiles.remove(worldPoint);
		retranslate();

		long senderId = pinged.senderMemberId;
		if (hiddenOnceSenderIds.remove(senderId))
		{
			blockedSenderIds.add(senderId);
			sendChatMessage("Ground Marker Variables: " + pinged.senderName + " blocked. Turn off Show Pinged Tiles to disable this feature.");
		}
		else
		{
			hiddenOnceSenderIds.add(senderId);
			sendChatMessage("Ground Marker Variables: Marker hidden from " + pinged.senderName + ". Hide one more to block them for this party session.");
		}
	}

	private void save(WorldPoint worldPoint, PingedTile pinged)
	{
		GroundMarkerPointData point = new GroundMarkerPointData(worldPoint.getRegionID(), worldPoint.getRegionX(), worldPoint.getRegionY(),
			worldPoint.getPlane(), pinged.marker.source.getColor(), pinged.marker.source.getLabel());
		markerStorage.addPoints(List.of(point));
		plugin.loadPoints();
		pingedTiles.remove(worldPoint);
		retranslate();
		sendChatMessage("Ground Marker saved from " + pinged.senderName + ".");
	}

	private void sendChatMessage(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	public Collection<TranslatedPingedTile> getTranslatedPingedTiles(WorldView wv)
	{
		return translatedByWorldView.getOrDefault(wv, Collections.emptyList());
	}
}

package com.groundmarkervariables.party;

import net.runelite.api.coords.WorldPoint;

// A pinged tile's position after instance translation. Mirrors TranslatedMarker, computed the
// same way (once per tick, not per render() call) by PingedTileManager.
public class TranslatedPingedTile
{
	public final WorldPoint worldPoint;
	public final PingedTile tile;

	TranslatedPingedTile(WorldPoint worldPoint, PingedTile tile)
	{
		this.worldPoint = worldPoint;
		this.tile = tile;
	}
}

package com.groundmarkervariables.variables;

import com.groundmarkervariables.GroundMarkerVariablesConfig;
import com.groundmarkervariables.variables.label.BooleanVariable;
import com.groundmarkervariables.variables.label.ConditionalVariable;
import com.groundmarkervariables.variables.label.MathVariable;
import com.groundmarkervariables.variables.label.MetronomeLabelVariable;
import com.groundmarkervariables.variables.support.Emojis;
import com.groundmarkervariables.variables.support.NamedColors;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

// Applies every registered LabelVariable to a marker's label. To add a new base variable
// (one usable directly and inside a {expr == value ? a : b} conditional): write a
// LabelVariable implementation and add it to VariableRegistry — nothing here needs to
// change. BooleanVariable and ConditionalVariable are listed separately since they depend on
// that same registry via ConditionEvaluator (see VariableRegistry's comment for why).
//
// MetronomeLabelVariable is listed separately too, deliberately LAST (after conditional)
// Per Plugin Hub review, metronomes inside of conditionals are too risky for abuse.
public class LabelResolver
{
	private static final Pattern HAS_VARIABLE = Pattern.compile(".*\\{.*\\}.*", Pattern.DOTALL);

	private final List<LabelVariable> baseVariables;
	private final MathVariable math;
	private final BooleanVariable booleanVariable;
	private final ConditionalVariable conditional;
	private final MetronomeLabelVariable metronome;
	private final GroundMarkerVariablesConfig config;
	private final Emojis emojis;

	// Built lazily per variable, then reused -- this instance is shared by every CachedMarker.
	private final Map<LabelVariable, Pattern> prefixedPatterns = new HashMap<>();

	@Inject
	private LabelResolver(VariableRegistry registry, MathVariable math, BooleanVariable booleanVariable, ConditionalVariable conditional,
						  MetronomeLabelVariable metronome, GroundMarkerVariablesConfig config, Emojis emojis)
	{
		this.baseVariables = registry.all();
		this.math = math;
		this.booleanVariable = booleanVariable;
		this.conditional = conditional;
		this.metronome = metronome;
		this.config = config;
		this.emojis = emojis;
	}

	// A marker's own raw label: {col=} and :emoji: aliases expand first, so neither is mistaken
	// for {variable} / {cond ? a : b} syntax.
	public String resolveMarker(String label)
	{
		return resolve(emojis.expand(label == null ? null : NamedColors.expandColorAliases(label)));
	}

	public String resolve(String label)
	{
		if (label == null || !HAS_VARIABLE.matcher(label).matches())
		{
			return label;
		}

		// Runs first, while a branch's own nested token is still literal -- otherwise its
		// resolved text (e.g. a colon in Rich Text) could corrupt the ?/: split. Also forces
		// Plain for its own <expr> internally (no ^/&/* support).
		String resolved = conditional.resolveAll(label);

		resolved = applyWithMode(math, resolved);
		for (LabelVariable variable : baseVariables)
		{
			resolved = applyWithMode(variable, resolved);
		}

		// {expr cmp value} with no ?/: — disjoint from conditional's own ?/:-requiring pattern.
		resolved = applyWithMode(booleanVariable, resolved);

		// Metronome stays last, same as today — see the class comment on why.
		resolved = applyWithMode(metronome, resolved);

		return resolved;
	}

	// Matches this variable's token with an optional ^/&/* mode-override prefix right after
	// its opening brace, then re-matches the variable's own untouched pattern against the
	// prefix-stripped text so resolve() sees the exact match shape it always has.
	private String applyWithMode(LabelVariable variable, String text)
	{
		Pattern prefixed = prefixedPatterns.computeIfAbsent(variable, LabelResolver::withOptionalModePrefix);
		Matcher matcher = prefixed.matcher(text);
		StringBuilder replaced = new StringBuilder();
		while (matcher.find())
		{
			Character prefixChar = matcher.group(1) == null ? null : matcher.group(1).charAt(0);
			TextMode mode = TextMode.forPrefix(prefixChar, config.richTextByDefault());

			String bareToken = prefixChar == null ? matcher.group(0) : "{" + matcher.group(0).substring(2);
			Matcher bareMatcher = variable.pattern().matcher(bareToken);
			String value;
			try
			{
				value = bareMatcher.matches() ? variable.resolve(bareMatcher, mode) : null;
			}
			catch (RuntimeException e)
			{
				value = "ERROR";
			}
			if (value != null)
			{
				matcher.appendReplacement(replaced, Matcher.quoteReplacement(value));
			}
		}
		matcher.appendTail(replaced);
		return replaced.toString();
	}

	// Every LabelVariable pattern starts with the literal "\{" -- inserting the optional
	// prefix group right after it leaves the rest of the pattern, and its group numbering,
	// untouched.
	private static Pattern withOptionalModePrefix(LabelVariable variable)
	{
		String source = variable.pattern().pattern();
		return Pattern.compile("\\{(?:([\\^&*]))?" + source.substring(2), variable.pattern().flags());
	}
}

package com.groundmarkervariables.variables;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

// A {token} substitution ground marker labels can use, e.g. {rsn} or {metronome5}. A regex
// rather than a literal string because some variables carry their own parameters (the "5"
// in {metronome5}) that resolve() needs to read back out of the match via capture groups.
public interface LabelVariable
{
	// Matches every occurrence of this variable in a label, e.g. Pattern.compile("\\{rsn\\}").
	Pattern pattern();

	// Today's concise output, or null if unresolvable (e.g. not logged in yet) -- the match is
	// then left as-is.
	String resolvePlain(Matcher matcher);

	// The more descriptive Rich Text output -- see RichText.
	String resolveRich(Matcher matcher);

	// LabelResolver's dispatch point when it doesn't already know which one it wants; call
	// resolvePlain/resolveRich directly when it does (see ConditionalVariable, always Plain).
	default String resolve(Matcher matcher, TextMode mode)
	{
		return mode == TextMode.RICH ? resolveRich(matcher) : resolvePlain(matcher);
	}
}

