package com.groundmarkervariables.variables.label;

import com.groundmarkervariables.GroundMarkerVariablesConfig;
import com.groundmarkervariables.variables.LabelVariable;
import com.groundmarkervariables.variables.RichText;
import com.groundmarkervariables.variables.support.ConditionEvaluator;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

// {<expr> <cmp> <value>} — colors <expr>'s own Plain Text value true/false, no ?/: branches.
// ? excluded from both groups so this can't collide with real {cond ? A : B} syntax (every
// real conditional has a literal '?' before any ':', so that alone is enough -- <value> still
// allows ':' for clock-time values like {time < 9:00}).
//
// {6HourTimeRemaining < <hours>} / {6HourTimeRemaining <= <hours>} is a special case: <hours>
// is a plain number of hours (or "h:mm") against the live Duration, not the generic comparison
// above (which would misread "1:45" as a clock time). Rich: false is the normal Rich Text, true
// swaps in Boolean False Color as a warning. Plain: false is "", true is the bare value. Any
// other comparator with this variable resolves to a call-to-action instead.
public class BooleanVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile(
		"\\{\\s*([^{}?:]+?)\\s*(==|!=|<=|>=|<|>)\\s*([^{}?]+?)\\s*\\}");
	private static final String UNSUPPORTED_COMPARATOR_TEXT = "Use {6HourTimeRemaining < 1.5} for a 1.5 hour warning";

	private final ConditionEvaluator evaluator;
	private final RichText richText;
	private final SixHourTimeRemainingLabelVariable sixHourTimeRemaining;
	private final GroundMarkerVariablesConfig config;

	@Inject
	private BooleanVariable(ConditionEvaluator evaluator, RichText richText,
                            SixHourTimeRemainingLabelVariable sixHourTimeRemaining, GroundMarkerVariablesConfig config)
	{
		this.evaluator = evaluator;
		this.richText = richText;
		this.sixHourTimeRemaining = sixHourTimeRemaining;
		this.config = config;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		if (isSixHourTimeRemaining(matcher.group(1)))
		{
			return resolveSixHourWarning(matcher, false);
		}

		String value = evaluator.resolveExpression(matcher.group(1));
		if (value == null)
		{
			return null;
		}

		return evaluator.evaluate(value, matcher.group(2), matcher.group(3)) == null ? null : value;
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		if (isSixHourTimeRemaining(matcher.group(1)))
		{
			return resolveSixHourWarning(matcher, true);
		}

		String value = evaluator.resolveExpression(matcher.group(1));
		if (value == null)
		{
			return null;
		}

		Boolean result = evaluator.evaluate(value, matcher.group(2), matcher.group(3));
		return result == null ? null : richText.booleanColored(result, value);
	}

	private boolean isSixHourTimeRemaining(String expr)
	{
		return evaluator.isSixHourTimeRemaining(expr);
	}

	private String resolveSixHourWarning(Matcher matcher, boolean rich)
	{
		String comparator = matcher.group(2);
		if (!"<".equals(comparator) && !"<=".equals(comparator))
		{
			return UNSUPPORTED_COMPARATOR_TEXT;
		}

		Boolean warning = evaluator.evaluateCondition(matcher.group(1), comparator, matcher.group(3));
		if (warning == null)
		{
			return null;
		}

		if (!warning)
		{
			return rich ? sixHourTimeRemaining.resolveRich(matcher) : "";
		}

		return rich ? sixHourTimeRemaining.richTextWithColor(config.booleanFalseColor()) : sixHourTimeRemaining.formatPlain();
	}
}

package com.groundmarkervariables.variables.label;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

import com.groundmarkervariables.variables.LabelVariable;
import com.groundmarkervariables.variables.RichText;
import com.groundmarkervariables.variables.support.SkillFinder;
import net.runelite.api.Client;
import net.runelite.api.Skill;

// {boost_<skill>} -> the player's current boosted (post potion/prayer/curse) level in
// <skill>, e.g. {boost_attack}, {boost_hitpoints}, {boost_mining}. <skill> matches any
// Skill.getName() case-insensitively, same as {lvl_<skill>}. Uses getBoostedSkillLevel(),
// not getRealSkillLevel() — the opposite of SkillLevelLabelVariable.
public class BoostedSkillLevelLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{boost_([a-z]+)\\}", Pattern.CASE_INSENSITIVE);

	private final Client client;
	private final RichText richText;

	@Inject
	private BoostedSkillLevelLabelVariable(Client client, RichText richText)
	{
		this.client = client;
		this.richText = richText;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		Skill skill = SkillFinder.find(matcher.group(1));
		return skill == null ? null : String.valueOf(client.getBoostedSkillLevel(skill));
	}

	// Needs the real level too, so this doesn't delegate to resolvePlain.
	@Override
	public String resolveRich(Matcher matcher)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		Skill skill = SkillFinder.find(matcher.group(1));
		if (skill == null)
		{
			return null;
		}

		int boosted = client.getBoostedSkillLevel(skill);
		int real = client.getRealSkillLevel(skill);
		return skill.getName() + ": " + richText.highlightValue(String.valueOf(boosted)) + " / " + real;
	}
}

package com.groundmarkervariables.variables.label;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

import com.groundmarkervariables.variables.LabelVariable;
import com.groundmarkervariables.variables.RichText;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;

// {combatAchievement} (or its {combatAchievements} alias) -> current CA reward tier, 0-6.
public class CombatAchievementsLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{combatAchievements?\\}", Pattern.CASE_INSENSITIVE);

	private static final String[] TIER_NAMES = {"Easy", "Medium", "Hard", "Elite", "Master", "Grandmaster"};
	private static final int[] TIER_THRESHOLDS = {
		VarbitID.CA_THRESHOLD_EASY, VarbitID.CA_THRESHOLD_MEDIUM, VarbitID.CA_THRESHOLD_HARD,
		VarbitID.CA_THRESHOLD_ELITE, VarbitID.CA_THRESHOLD_MASTER, VarbitID.CA_THRESHOLD_GRANDMASTER
	};

	private final Client client;
	private final RichText richText;

	@Inject
	private CombatAchievementsLabelVariable(Client client, RichText richText)
	{
		this.client = client;
		this.richText = richText;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		return String.valueOf(tier());
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		int tier = tier();
		return richText.labeled("Combat Achievement tier", tier == 0 ? "None" : TIER_NAMES[tier - 1]);
	}

	// Count of tier thresholds the player's points have reached.
	private int tier()
	{
		int points = client.getVarbitValue(VarbitID.CA_POINTS);
		int tier = 0;
		for (int threshold : TIER_THRESHOLDS)
		{
			if (points < client.getVarbitValue(threshold))
			{
				break;
			}
			tier++;
		}
		return tier;
	}
}

package com.groundmarkervariables.variables.label;

import com.groundmarkervariables.variables.LabelVariable;
import com.groundmarkervariables.variables.support.ConditionEvaluator;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

// {<chain> ? <whenTrue> [: <whenFalse>]} — <chain> is any number of "<expr> [<cmp> <value>]"
// leaves combined with && / ||, with parens overriding the usual && before || precedence.
// Branches may contain {...} tokens nested to any depth, including conditionals, e.g.
// {a ? {b ? X : Y} : Z}. Base variables in the winning branch resolve in LabelResolver's later
// passes; metronome is neutralized here, a metavariable left for MetaVariableResolver.
public class ConditionalVariable implements LabelVariable
{
	private static final String METRONOME_TOKEN =
		"(?i:\\{(?:metronome|m)[+-]?\\d+(?:_\\d+)?\\})";
	private static final Pattern METRONOME_TOKEN_PATTERN = Pattern.compile(METRONOME_TOKEN);
	private static final String NESTED_TOKEN = "\\{[^{}]*\\}";

	private static final Pattern LEAF = Pattern.compile("([^{}]+?)\\s*(?:(==|!=|<=|>=|<|>)\\s*([^{}]+?)\\s*)?");
	private static final Pattern PATTERN = Pattern.compile(
		"\\{([^{}?]+\\?(?:[^{}]|" + NESTED_TOKEN + ")+)\\}");

	private final ConditionEvaluator evaluator;

	@Inject
	private ConditionalVariable(ConditionEvaluator evaluator)
	{
		this.evaluator = evaluator;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	// No Rich/Plain distinction of its own -- output is whichever branch's literal text won.
	@Override
	public String resolvePlain(Matcher matcher)
	{
		return resolveConditional(matcher);
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		return resolveConditional(matcher);
	}

	private String resolveConditional(Matcher matcher)
	{
		return resolveToken(matcher.group());
	}

	// Resolves each top-level {...} conditional in text. Other tokens are left as-is.
	public String resolveAll(String text)
	{
		StringBuilder out = new StringBuilder();
		int i = 0;
		while (i < text.length())
		{
			int open = text.indexOf('{', i);
			int close = open < 0 ? -1 : matchingBrace(text, open);
			if (close < 0)
			{
				out.append(text, i, text.length());
				break;
			}

			String token = text.substring(open, close + 1);
			String resolved;
			try
			{
				resolved = resolveToken(token);
			}
			catch (RuntimeException e)
			{
				resolved = "ERROR";
			}
			out.append(text, i, open).append(resolved == null ? token : resolved);
			i = close + 1;
		}
		return out.toString();
	}

	// Null if token isn't a resolvable conditional. Only the winning branch's own nested
	// conditionals are resolved.
	private String resolveToken(String token)
	{
		String inner = token.substring(1, token.length() - 1);
		int question = topLevel(inner, 0, '?');
		if (question < 0 || inner.substring(0, question).contains("{"))
		{
			return null;
		}

		Boolean result = evaluate(inner.substring(0, question));
		if (result == null)
		{
			return null;
		}

		// No : means an empty else.
		int colon = topLevel(inner, question + 1, ':');
		String whenTrue = colon < 0 ? inner.substring(question + 1) : inner.substring(question + 1, colon);
		String whenFalse = colon < 0 ? "" : inner.substring(colon + 1);
		String winner = METRONOME_TOKEN_PATTERN.matcher((result ? whenTrue : whenFalse).trim()).replaceAll("ILLEGAL");
		return resolveAll(winner);
	}

	private static int matchingBrace(String text, int open)
	{
		int depth = 0;
		for (int i = open; i < text.length(); i++)
		{
			char c = text.charAt(i);
			if (c == '{')
			{
				depth++;
			}
			else if (c == '}' && --depth == 0)
			{
				return i;
			}
		}
		return -1;
	}

	// First c outside any {...} at or after from. A : between digits (9:00) doesn't count.
	private static int topLevel(String text, int from, char c)
	{
		int depth = 0;
		for (int i = from; i < text.length(); i++)
		{
			char ch = text.charAt(i);
			if (ch == '{')
			{
				depth++;
			}
			else if (ch == '}')
			{
				depth--;
			}
			else if (depth == 0 && ch == c && !(c == ':' && isClockColon(text, i)))
			{
				return i;
			}
		}
		return -1;
	}

	private static boolean isClockColon(String text, int i)
	{
		return i > 0 && i + 1 < text.length() && Character.isDigit(text.charAt(i - 1)) && Character.isDigit(text.charAt(i + 1));
	}

	// Splits on top-level (paren-depth 0) && / ||, then collapses && pairs before || pairs --
	// same flat two-pass shape as MathVariable's own * / before + -.
	private Boolean evaluate(String text)
	{
		List<Boolean> values = new ArrayList<>();
		List<String> operators = new ArrayList<>();

		int depth = 0;
		int last = 0;
		for (int i = 0; i < text.length(); i++)
		{
			char c = text.charAt(i);
			if (c == '(')
			{
				depth++;
			}
			else if (c == ')')
			{
				depth--;
			}
			else if (depth == 0 && (text.startsWith("&&", i) || text.startsWith("||", i)))
			{
				values.add(evaluateFactor(text.substring(last, i)));
				operators.add(text.substring(i, i + 2));
				i++;
				last = i + 1;
			}
		}
		values.add(evaluateFactor(text.substring(last)));

		for (int i = 0; i < operators.size(); )
		{
			if (!"&&".equals(operators.get(i)))
			{
				i++;
				continue;
			}

			values.set(i, and(values.get(i), values.get(i + 1)));
			values.remove(i + 1);
			operators.remove(i);
		}

		Boolean result = values.get(0);
		for (Boolean value : values.subList(1, values.size()))
		{
			result = or(result, value);
		}
		return result;
	}

	// A factor fully wrapped in one matching paren pair recurses; otherwise it's a leaf. A
	// leaf's own <expr>/<value> may still contain balanced parens of its own (e.g. a
	// MathVariable expression) -- those are left untouched for ConditionEvaluator to resolve.
	private Boolean evaluateFactor(String text)
	{
		String trimmed = text.trim();
		if (isFullyWrapped(trimmed))
		{
			return evaluate(trimmed.substring(1, trimmed.length() - 1));
		}

		Matcher leaf = LEAF.matcher(trimmed);
		return leaf.matches() ? evaluator.evaluateCondition(leaf.group(1), leaf.group(2), leaf.group(3)) : null;
	}

	private static boolean isFullyWrapped(String text)
	{
		if (text.length() < 2 || text.charAt(0) != '(' || text.charAt(text.length() - 1) != ')')
		{
			return false;
		}

		int depth = 0;
		for (int i = 0; i < text.length(); i++)
		{
			if (text.charAt(i) == '(')
			{
				depth++;
			}
			else if (text.charAt(i) == ')')
			{
				depth--;
				if (depth == 0 && i != text.length() - 1)
				{
					return false;
				}
			}
		}
		return depth == 0;
	}

	// Three-valued AND: false wins regardless of the other side (even if unresolvable);
	// otherwise null propagates unless both sides are known true.
	private static Boolean and(Boolean a, Boolean b)
	{
		if (Boolean.FALSE.equals(a) || Boolean.FALSE.equals(b))
		{
			return Boolean.FALSE;
		}

		return (a == null || b == null) ? null : Boolean.TRUE;
	}

	// Three-valued OR: true wins regardless of the other side; otherwise null propagates
	// unless both sides are known false.
	private static Boolean or(Boolean a, Boolean b)
	{
		if (Boolean.TRUE.equals(a) || Boolean.TRUE.equals(b))
		{
			return Boolean.TRUE;
		}

		return (a == null || b == null) ? null : Boolean.FALSE;
	}
}

package com.groundmarkervariables.variables.label;

import com.groundmarkervariables.variables.LabelVariable;
import com.groundmarkervariables.variables.RichText;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

// {date} -- today's date (midnight, no time component), e.g. "October 12th 2026". Usable in
// MathVariable for a countdown, e.g. {Oct 20 - date}.
public class DateLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{date\\}", Pattern.CASE_INSENSITIVE);
	private static final DateTimeFormatter FORMAT = DateTimeFormatter.ofPattern("MMMM d", Locale.ENGLISH);

	private final RichText richText;

	@Inject
	private DateLabelVariable(RichText richText)
	{
		this.richText = richText;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		LocalDate today = LocalDate.now();
		return today.format(FORMAT) + ordinalSuffix(today.getDayOfMonth()) + " " + today.getYear();
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		return richText.labeled("Date", resolvePlain(matcher));
	}

	// 11th/12th/13th are always "th"; otherwise it follows the last digit (1st, 2nd, 3rd, 4th...).
	private static String ordinalSuffix(int day)
	{
		if (day >= 11 && day <= 13)
		{
			return "th";
		}

		switch (day % 10)
		{
			case 1:
				return "st";
			case 2:
				return "nd";
			case 3:
				return "rd";
			default:
				return "th";
		}
	}
}

package com.groundmarkervariables.variables.label;

import java.awt.Color;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;

import com.groundmarkervariables.variables.LabelVariable;
import com.groundmarkervariables.variables.RichText;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;

// {divine <potion>} -> ticks remaining on <potion>'s buff. Rich is the potion's name colored
// green (>25 ticks), yellow (1-25), or red (0, not active).
@Singleton
public class DivineLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{divine\\s+([^{}?:<>=!]+?)\\}", Pattern.CASE_INSENSITIVE);
	private static final int YELLOW_THRESHOLD = 25;
	private static final int REFRESH_TICKS = 25;

	// Per refresh varbit, as last seen while resolving.
	private static final class RefreshState
	{
		private int lastValue = -1;
		private int lastSeenTick = -1;
		private Integer nextRefreshTick;
	}

	private final Map<Integer, RefreshState> refreshStates = new HashMap<>();

	private enum Potion
	{
		ATTACK("attack", "Divine Super Attack Potion", VarbitID.DIVINEATTACK_POTION_TIME, VarbitID.DIVINECOMBAT_POTION_TIME),
		STRENGTH("strength", "Divine Super Strength Potion", VarbitID.DIVINESTRENGTH_POTION_TIME, VarbitID.DIVINECOMBAT_POTION_TIME),
		DEFENCE("defence", "Divine Super Defence Potion", VarbitID.DIVINEDEFENCE_POTION_TIME,
			VarbitID.DIVINECOMBAT_POTION_TIME, VarbitID.DIVINEBASTION_POTION_TIME, VarbitID.DIVINEBATTLEMAGE_POTION_TIME),
		RANGE("range", "Divine Ranging Potion", VarbitID.DIVINERANGE_POTION_TIME, VarbitID.DIVINEBASTION_POTION_TIME),
		MAGIC("magic", "Divine Magic Potion", VarbitID.DIVINEMAGIC_POTION_TIME, VarbitID.DIVINEBATTLEMAGE_POTION_TIME),
		COMBAT("combat", "Divine Super Combat Potion", VarbitID.DIVINECOMBAT_POTION_TIME),
		BASTION("bastion", "Divine Bastion Potion", VarbitID.DIVINEBASTION_POTION_TIME),
		BATTLEMAGE("battlemage", "Divine Battlemage Potion", VarbitID.DIVINEBATTLEMAGE_POTION_TIME),
		SALTS("salts", "Smelling Salts", true, VarbitID.TOA_MIDRAIDLOOT_STATS_TIMER),
		OVERLOAD("overload", "Overload", true, VarbitID.RAIDS_OVERLOAD_TIMER,
			VarbitID.NZONE_OVERLOAD_POTION_EFFECTS, VarbitID.DEADMAN_OVERLOAD_POTION_EFFECTS);

		private final String keyword;
		private final String displayName;
		// Varbit counts 25-tick stat refreshes left instead of ticks.
		private final boolean refreshes;
		private final int[] varbits;

		Potion(String keyword, String displayName, int... varbits)
		{
			this(keyword, displayName, false, varbits);
		}

		Potion(String keyword, String displayName, boolean refreshes, int... varbits)
		{
			this.keyword = keyword;
			this.displayName = displayName;
			this.refreshes = refreshes;
			this.varbits = varbits;
		}

		private static Potion find(String text)
		{
			for (Potion potion : values())
			{
				if (potion.keyword.equalsIgnoreCase(text))
				{
					return potion;
				}
			}
			return null;
		}
	}

	private final Client client;

	@Inject
	private DivineLabelVariable(Client client)
	{
		this.client = client;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		Potion potion = Potion.find(matcher.group(1).trim());
		if (potion == null || client.getLocalPlayer() == null)
		{
			return null;
		}

		return String.valueOf(ticks(potion));
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		Potion potion = Potion.find(matcher.group(1).trim());
		if (potion == null || client.getLocalPlayer() == null)
		{
			return null;
		}

		int ticks = ticks(potion);
		Color color = ticks == 0 ? Color.RED : ticks <= YELLOW_THRESHOLD ? Color.YELLOW : Color.GREEN;
		return RichText.colored(color, potion.displayName);
	}

	private int ticks(Potion potion)
	{
		int max = 0;
		for (int varbit : potion.varbits)
		{
			max = Math.max(max, potion.refreshes ? refreshTicks(varbit) : client.getVarbitValue(varbit));
		}
		return max;
	}

	// Times the next refresh from the tick the varbit was seen changing, like core's Timers & Buffs
	// overload timer. Until a change has been seen on consecutive ticks, estimates a full period.
	private int refreshTicks(int varbit)
	{
		int value = client.getVarbitValue(varbit);
		int tick = client.getTickCount();
		RefreshState state = refreshStates.computeIfAbsent(varbit, v -> new RefreshState());

		if (value <= 0)
		{
			state.nextRefreshTick = null;
		}
		else if (value != state.lastValue)
		{
			if (state.lastSeenTick < tick - 1)
			{
				state.nextRefreshTick = null;
			}
			else if (state.nextRefreshTick == null || state.nextRefreshTick <= tick)
			{
				state.nextRefreshTick = tick + REFRESH_TICKS;
			}
		}

		state.lastValue = value;
		state.lastSeenTick = tick;

		if (value <= 0)
		{
			return 0;
		}

		int untilNext = state.nextRefreshTick == null ? REFRESH_TICKS : Math.max(0, state.nextRefreshTick - tick);
		return untilNext + (value - 1) * REFRESH_TICKS;
	}
}

