import com.groundmarkervariables.variables.support.CollectionLog;
import com.groundmarkervariables.variables.support.PendingNpcLoot;
import com.groundmarkervariables.variables.support.RecentLootTracker;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.QuantityFormatter;

// {loot <monster>[, items=N][, lines=N][, itemsOnly]} -> gp value of loot Loot Tracker has recorded for
// <monster> (or the boss it's a BossAliases short name for), or 0 if none. itemsOnly shows just the items.
public class LootLabelVariable implements LabelVariable
{
	// Excludes ?:<>=! so a trailing comparator (e.g. "{loot monster > 10000}") isn't swallowed
	// into the monster name. Group 2 is the options.
	private static final Pattern PATTERN = Pattern.compile(
		"\\{loot\\s+([^{}?:<>=!]+?)((?:\\s*,?\\s*(?:itemsOnly|(?:items|lines)=\\d+))*)\\s*,?\\s*\\}", Pattern.CASE_INSENSITIVE);
	private static final Pattern OPTION = Pattern.compile("(items|lines)=(\\d+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern ITEMS_ONLY = Pattern.compile("itemsOnly", Pattern.CASE_INSENSITIVE);
	static final String GROUP = "loottracker";
	static final String KEY_PREFIX = "drops_";

	// Names that combine several Loot Tracker entries -- shared with AdvancedLabelEditor.
	public static final Map<String, List<String>> COMBINED_MONSTERS = Map.of(
		"Royal Titans", List.of("Eldric the Ice King", "Branda the Fire Queen"));
	public static final List<String> PLAYER_NAMES = List.of("players", "pk", "pker");
	public static final String PLAYER_TYPE = "PLAYER";
	private static final String PLAYERS_DISPLAY_NAME = "PKs";

	// Rich Text lists every pet, then up to items=N collection log or MIN_ITEM_VALUE+ items.
	private static final long MIN_ITEM_VALUE = 300_000;
	private static final int DEFAULT_ITEMS_SHOWN = 5;

	private final ConfigManager configManager;
	private final ItemManager itemManager;
	private final Gson gson;
	private final RecentLootTracker recentLootTracker;
	private final RichText richText;
	private final CollectionLog collectionLog;

	@Inject
	private LootLabelVariable(ConfigManager configManager, ItemManager itemManager, Gson gson, RecentLootTracker recentLootTracker,
		RichText richText, CollectionLog collectionLog)
	{
		this.configManager = configManager;
		this.itemManager = itemManager;
		this.gson = gson;
		this.recentLootTracker = recentLootTracker;
		this.richText = richText;
		this.collectionLog = collectionLog;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		Loot loot = loot(matcher);
		if (loot == null)
		{
			return null;
		}
		return itemsOnly(matcher) ? itemsOnlyText(loot.notableItems, option(matcher, "lines", 1)) : String.valueOf(loot.gp);
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		Loot loot = loot(matcher);
		if (loot == null)
		{
			return null;
		}
		if (itemsOnly(matcher))
		{
			return itemsOnlyText(loot.notableItems, option(matcher, "lines", 1));
		}

		String header = loot.monster + " (" + richText.highlightValue(String.valueOf(loot.kills)) + "): "
			+ richText.highlightValue(QuantityFormatter.quantityToStackSize(loot.gp));
		List<NotableItem> items = loot.notableItems;

		int lines = option(matcher, "lines", 1);
		if (lines <= 1)
		{
			return items.isEmpty() ? header : header + " | " + itemsText(items);
		}

		// Like {party}; items split evenly over the remaining lines, earlier lines taking extras.
		StringBuilder sb = new StringBuilder("{align=left}").append(header);
		int itemLines = Math.min(lines - 1, items.size());
		int start = 0;
		for (int line = 0; line < itemLines; line++)
		{
			int linesLeft = itemLines - line;
			int count = (items.size() - start + linesLeft - 1) / linesLeft;
			sb.append("\\n").append(itemsText(items.subList(start, start + count)));
			start += count;
		}
		return sb.append("\\n{/align}").toString();
	}

	private static boolean itemsOnly(Matcher matcher)
	{
		return ITEMS_ONLY.matcher(matcher.group(2)).find();
	}

	// The items split evenly over lines, earlier lines taking extras.
	private static String itemsOnlyText(List<NotableItem> items, int lines)
	{
		if (lines <= 1 || items.size() <= 1)
		{
			return itemsText(items);
		}

		StringBuilder sb = new StringBuilder("{align=left}");
		int itemLines = Math.min(lines, items.size());
		int start = 0;
		for (int line = 0; line < itemLines; line++)
		{
			int linesLeft = itemLines - line;
			int count = (items.size() - start + linesLeft - 1) / linesLeft;
			sb.append(line == 0 ? "" : "\\n").append(itemsText(items.subList(start, start + count)));
			start += count;
		}
		return sb.append("\\n{/align}").toString();
	}

	// <item=ID> is GroundMarkerVariablesOverlay's own inline-icon tag.
	private static String itemsText(List<NotableItem> items)
	{
		StringBuilder sb = new StringBuilder();
		for (NotableItem item : items)
		{
			if (sb.length() > 0)
			{
				sb.append(' ');
			}
			sb.append(item.quantity).append("x <item=").append(item.itemId).append('>');
		}
		return sb.toString();
	}

	// The last "<name>=N" option, or fallback.
	private static int option(Matcher matcher, String name, int fallback)
	{
		int value = fallback;
		Matcher option = OPTION.matcher(matcher.group(2));
		while (option.find())
		{
			if (option.group(1).equalsIgnoreCase(name))
			{
				try
				{
					value = Integer.parseInt(option.group(2));
				}
				catch (NumberFormatException e)
				{
					value = Integer.MAX_VALUE;
				}
			}
		}
		return value;
	}

	private Loot loot(Matcher matcher)
	{
		String monster = matcher.group(1).trim();
		if (monster.isEmpty())
		{
			return null;
		}

		boolean players = PLAYER_NAMES.contains(monster.toLowerCase(Locale.ENGLISH));
		String name = players ? PLAYERS_DISPLAY_NAME : BossAliases.resolve(monster);
		List<String> parts = List.of(monster, name);
		boolean combined = false;
		for (Map.Entry<String, List<String>> entry : COMBINED_MONSTERS.entrySet())
		{
			if (entry.getKey().equalsIgnoreCase(monster))
			{
				name = entry.getKey();
				parts = entry.getValue();
				combined = true;
			}
		}

		String profile = configManager.getRSProfileKey();
		boolean found = false;
		int kills = 0;
		long gp = 0;
		Map<Integer, Integer> quantityByItem = new LinkedHashMap<>();

		for (String key : configManager.getRSProfileConfigurationKeys(GROUP, profile, KEY_PREFIX))
		{
			// "drops_<TYPE>_<name>" -- TYPE (NPC/EVENT/PLAYER/...) has no underscore of its own,
			// so the first one after the prefix is exactly where the name starts.
			String rest = key.substring(KEY_PREFIX.length());
			int typeEnd = rest.indexOf('_');
			if (typeEnd < 0)
			{
				continue;
			}
			String candidateName = rest.substring(typeEnd + 1);
			boolean matches = players
				? rest.substring(0, typeEnd).equalsIgnoreCase(PLAYER_TYPE)
				: parts.stream().anyMatch(candidateName::equalsIgnoreCase);
			if (!matches)
			{
				continue;
			}

			if (!found && !players && !combined)
			{
				name = candidateName;
			}
			found = true;

			LootConfigData data = gson.fromJson(configManager.getConfiguration(GROUP, profile, key), LootConfigData.class);
			kills += data.kills;
			if (data.drops != null)
			{
				for (int i = 0; i < data.drops.length - 1; i += 2)
				{
					int itemId = data.drops[i];
					int quantity = data.drops[i + 1];
					gp += (long) itemManager.getItemPrice(itemId) * quantity;
					quantityByItem.merge(itemId, quantity, Integer::sum);
				}
			}
		}

		// Loot Tracker hasn't written these kills to config yet -- see RecentLootTracker (NPCs only).
		Set<String> pendingChecked = new HashSet<>();
		for (String part : players ? List.<String>of() : parts)
		{
			PendingNpcLoot recent = pendingChecked.add(part.toLowerCase(Locale.ENGLISH)) ? recentLootTracker.get(part) : null;
			if (recent == null)
			{
				continue;
			}

			if (!found && !combined)
			{
				name = recent.displayName;
			}
			found = true;
			kills += recent.kills;
			gp += recent.gpValue;
			for (Map.Entry<Integer, Integer> entry : recent.itemQuantities.entrySet())
			{
				quantityByItem.merge(entry.getKey(), entry.getValue(), Integer::sum);
			}
		}

		if (!found)
		{
			return new Loot(name, 0, 0, List.of());
		}

		List<NotableItem> pets = new ArrayList<>();
		List<NotableItem> others = new ArrayList<>();
		for (Map.Entry<Integer, Integer> entry : quantityByItem.entrySet())
		{
			// Collection log ids are unnoted.
			int canonicalId = itemManager.canonicalize(entry.getKey());
			long price = itemManager.getItemPrice(entry.getKey());
			NotableItem item = new NotableItem(entry.getKey(), entry.getValue(), price);
			if (collectionLog.isPet(canonicalId))
			{
				pets.add(item);
			}
			else if (price >= MIN_ITEM_VALUE || collectionLog.contains(canonicalId))
			{
				others.add(item);
			}
		}
		others.sort(Comparator.comparingLong((NotableItem item) -> item.price).reversed());
		int maxItems = option(matcher, "items", DEFAULT_ITEMS_SHOWN);
		if (others.size() > maxItems)
		{
			others = others.subList(0, maxItems);
		}

		List<NotableItem> notableItems = new ArrayList<>(pets);
		notableItems.addAll(others);
		return new Loot(name, kills, gp, notableItems);
	}

	// Field names match Loot Tracker's own (package-private) ConfigLoot for Gson.
	private static final class LootConfigData
	{
		int kills;
		int[] drops;
	}

	private static final class Loot
	{
		final String monster;
		final int kills;
		final long gp;
		final List<NotableItem> notableItems;

		Loot(String monster, int kills, long gp, List<NotableItem> notableItems)
		{
			this.monster = monster;
			this.kills = kills;
			this.gp = gp;
			this.notableItems = notableItems;
		}
	}

	private static final class NotableItem
	{
		final int itemId;
		final int quantity;
		final long price;

		NotableItem(int itemId, int quantity, long price)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.price = price;
		}
	}
}

package com.groundmarkervariables.variables.label;

import com.groundmarkervariables.variables.LabelVariable;
import com.groundmarkervariables.variables.NumericVariableRegistry;
import com.groundmarkervariables.variables.RichText;
import com.groundmarkervariables.variables.support.ConditionEvaluator;
import com.groundmarkervariables.variables.support.DateLiteralParser;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.LocalTime;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

import net.runelite.client.util.QuantityFormatter;

// {<a> <op> <b> [<op> <c> ...]} -- arithmetic over NumericVariableRegistry's own variables
// and/or literal numbers (e.g. "5", "1.5k"). Parens override the usual * / before + -
// precedence. Not usable with {metronomeN}. Also supports "<date literal> - date" (or
// reversed) as a day-count countdown, since {date}'s own Plain Text isn't a number.
public class MathVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{([^{}]+?(?:\\s[+\\-*/]\\s[^{}]+?)+)\\}");
	private static final Pattern OPERATOR = Pattern.compile("\\s([+\\-*/])\\s");
	private static final String DATE_VARIABLE = "date";
	private static final String TIME_VARIABLE = "time";
	private static final String NOW_VARIABLE = "now";

	private final List<LabelVariable> numericVariables;
	private final RichText richText;

	@Inject
	private MathVariable(NumericVariableRegistry registry, RichText richText)
	{
		this.numericVariables = registry.all();
		this.richText = richText;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		try
		{
			Long minutes = evaluateTimeCountdown(matcher.group(1));
			if (minutes != null)
			{
				return formatMinutes(minutes, false);
			}

			Long days = evaluateDateCountdown(matcher.group(1));
			if (days != null)
			{
				return String.valueOf(days);
			}

			Double value = evaluate(matcher.group(1));
			return value == null ? null : formatPlain(value);
		}
		catch (RuntimeException e)
		{
			return "NaN";
		}
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		try
		{
			Long minutes = evaluateTimeCountdown(matcher.group(1));
			if (minutes != null)
			{
				return richText.highlightValue(formatMinutes(minutes, true));
			}

			Long days = evaluateDateCountdown(matcher.group(1));

			// "day(s)" only applies to a bare date pair -- once anything's chained after it
			// (a second operator), fall through to the normal plain-number formatting below.
			Matcher opMatcher = OPERATOR.matcher(matcher.group(1));
			if (days != null && opMatcher.find() && !opMatcher.find())
			{
				return richText.highlightValue(days + (days == 1 || days == -1 ? " day" : " days"));
			}

			Double value = days != null ? Double.valueOf(days) : evaluate(matcher.group(1));
			return value == null ? null : richText.highlightValue(QuantityFormatter.quantityToStackSize(Math.round(value)));
		}
		catch (RuntimeException e)
		{
			return "NaN";
		}
	}

	// Only matches if the FIRST operator is "-" and pairs "date" with a parseable date literal
	// as the first two operands -- date math only applies at the very start of a chain (or,
	// via evaluateInner(), the very start of a parenthesized group). Whatever follows (e.g.
	// "+ 2") is handled by the normal evaluate().
	private Long evaluateDateCountdown(String expression)
	{
		Matcher opMatcher = OPERATOR.matcher(expression);
		if (!opMatcher.find() || !"-".equals(opMatcher.group(1)))
		{
			return null;
		}

		String first = expression.substring(0, opMatcher.start()).trim();
		int secondStart = opMatcher.end();

		String second;
		String remainder;
		if (opMatcher.find())
		{
			second = expression.substring(secondStart, opMatcher.start()).trim();
			remainder = expression.substring(opMatcher.start());
		}
		else
		{
			second = expression.substring(secondStart).trim();
			remainder = "";
		}

		LocalDate firstDate = dateValueOf(first);
		LocalDate secondDate = dateValueOf(second);
		if (firstDate == null || secondDate == null)
		{
			return null;
		}

		long dayCount = ChronoUnit.DAYS.between(secondDate, firstDate);
		if (remainder.isEmpty())
		{
			return dayCount;
		}

		Double result = evaluate(dayCount + remainder);
		return result == null ? null : Math.round(result);
	}

	// "<a> - <b>" in minutes, between times (wrapping past midnight) or date times. Date pairs are
	// left to evaluateDateCountdown.
	private static Long evaluateTimeCountdown(String expression)
	{
		Matcher opMatcher = OPERATOR.matcher(expression);
		if (!opMatcher.find() || !"-".equals(opMatcher.group(1)))
		{
			return null;
		}

		String first = expression.substring(0, opMatcher.start()).trim();
		String second = expression.substring(opMatcher.end()).trim();
		if (opMatcher.find() || dateValueOf(first) != null && dateValueOf(second) != null)
		{
			return null;
		}

		Integer toMinute = minuteOfDay(first);
		Integer fromMinute = minuteOfDay(second);
		if (toMinute != null && fromMinute != null)
		{
			return (long) Math.floorMod(toMinute - fromMinute, 24 * 60);
		}

		LocalDateTime to = dateTimeValueOf(first);
		LocalDateTime from = dateTimeValueOf(second);
		return to == null || from == null ? null : ChronoUnit.MINUTES.between(from, to);
	}

	// "now", "<date>" (midnight) or "<date> <time>", e.g. "oct 30 7am".
	private static LocalDateTime dateTimeValueOf(String text)
	{
		if (NOW_VARIABLE.equalsIgnoreCase(text))
		{
			return LocalDateTime.now().truncatedTo(ChronoUnit.MINUTES);
		}

		String[] words = text.split("\\s+");
		for (int split = words.length; split > 0; split--)
		{
			LocalDate date = DateLiteralParser.parse(String.join(" ", Arrays.copyOfRange(words, 0, split)));
			String timeText = String.join(" ", Arrays.copyOfRange(words, split, words.length));
			Integer minute = timeText.isEmpty() ? Integer.valueOf(0) : minuteOfDay(timeText);
			if (date != null && minute != null)
			{
				return date.atStartOfDay().plusMinutes(minute);
			}
		}
		return null;
	}

	// h:mm, negative in the past. Rich splits off days, e.g. "3 days 3:12".
	private static String formatMinutes(long minutes, boolean rich)
	{
		long abs = Math.abs(minutes);
		long days = rich ? abs / (24 * 60) : 0;
		long rest = abs - days * 24 * 60;
		String time = String.format("%d:%02d", rest / 60, rest % 60);
		return (minutes < 0 ? "-" : "") + (days == 0 ? time : days + (days == 1 ? " day " : " days ") + time);
	}

	// "time"/"now" is the current time. Bare numbers stay numbers, so {5 - 3} is still 2.
	private static Integer minuteOfDay(String text)
	{
		if (TIME_VARIABLE.equalsIgnoreCase(text) || NOW_VARIABLE.equalsIgnoreCase(text))
		{
			return LocalTime.now().toSecondOfDay() / 60;
		}

		if (ConditionEvaluator.tryParseNumber(text) != null)
		{
			return null;
		}

		LocalTime time = ConditionEvaluator.tryParseTime(text);
		return time == null ? null : time.toSecondOfDay() / 60;
	}

	// "date"/"now" means today; otherwise must parse as a date literal.
	private static LocalDate dateValueOf(String text)
	{
		return DATE_VARIABLE.equalsIgnoreCase(text) || NOW_VARIABLE.equalsIgnoreCase(text) ? LocalDate.now() : DateLiteralParser.parse(text);
	}

	// Reduces the innermost "(...)" first, then moves outwards. Paren is always space padded.
	private Double evaluate(String expression)
	{
		String reduced = expression;
		while (reduced.contains("("))
		{
			int close = reduced.indexOf(')');
			if (close < 0)
			{
				return null;
			}

			int open = reduced.lastIndexOf('(', close);
			if (open < 0)
			{
				return null;
			}

			Double inner = evaluateInner(reduced.substring(open + 1, close));
			if (inner == null)
			{
				return null;
			}

			reduced = reduced.substring(0, open) + formatPlain(inner) + reduced.substring(close + 1);
		}

		return evaluateFlat(reduced);
	}

	// A paren group's own content may itself start with a date pairing.
	private Double evaluateInner(String text)
	{
		Long days = evaluateDateCountdown(text);
		return days != null ? Double.valueOf(days) : evaluateFlat(text);
	}

	// Splits on whitespace-padded operators, resolves every operand, then applies standard
	// precedence (* and / before + and -) left to right within each pass.
	private Double evaluateFlat(String expression)
	{
		List<Double> operands = new ArrayList<>();
		List<Character> operators = new ArrayList<>();

		Matcher opMatcher = OPERATOR.matcher(expression);
		int last = 0;
		while (opMatcher.find())
		{
			Double operand = resolveOperand(expression.substring(last, opMatcher.start()));
			if (operand == null)
			{
				return null;
			}
			operands.add(operand);
			operators.add(opMatcher.group(1).charAt(0));
			last = opMatcher.end();
		}

		Double finalOperand = resolveOperand(expression.substring(last));
		if (finalOperand == null)
		{
			return null;
		}
		operands.add(finalOperand);

		for (int i = 0; i < operators.size(); )
		{
			char op = operators.get(i);
			if (op != '*' && op != '/')
			{
				i++;
				continue;
			}

			double left = operands.get(i);
			double right = operands.get(i + 1);
			if (op == '/' && right == 0)
			{
				return null;
			}

			operands.set(i, op == '*' ? left * right : left / right);
			operands.remove(i + 1);
			operators.remove(i);
		}

		double total = operands.get(0);
		for (int i = 0; i < operators.size(); i++)
		{
			total = operators.get(i) == '+' ? total + operands.get(i + 1) : total - operands.get(i + 1);
		}

		return total;
	}

	// A literal number (plain or "1.5k"-style), or another variable's own Plain Text value.
	private Double resolveOperand(String text)
	{
		text = text.trim();
		Double literal = ConditionEvaluator.tryParseNumber(text);
		if (literal != null)
		{
			return literal;
		}

		for (LabelVariable variable : numericVariables)
		{
			Matcher wrapped = variable.pattern().matcher("{" + text + "}");
			if (wrapped.matches())
			{
				String resolved = variable.resolvePlain(wrapped);
				return resolved == null ? null : ConditionEvaluator.tryParseNumber(resolved);
			}
		}

		return null;
	}

	private static String formatPlain(double value)
	{
		return value == Math.rint(value) && !Double.isInfinite(value)
			? String.valueOf((long) value)
			: String.valueOf(value);
	}
}

package com.groundmarkervariables.variables.label;

import com.groundmarkervariables.GroundMarkerVariablesConfig;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;

import com.groundmarkervariables.variables.LabelVariable;
import net.runelite.api.Client;
import net.runelite.client.party.PartyService;
import net.runelite.client.util.ColorUtil;

// {metronomeN} (or its {mN} alias) counts up from 1 to N, or with the "Count Down" config
// option, down from N to 1, then repeats, advancing once per game tick. {metronomeN_M} is
// the same, but only advances once every M ticks (default M = 1). Driven
// by Client.getTickCount() rather than our own counter so it stays exact regardless of how
// often the overlay redraws, and so every {metronomeN_M} with the same N and M stays in sync
// — offset by the "Reset metronome" hotkey's tick (see offset()) so every metronome can be
// re-synced to a moment the player chooses, e.g. the start of a boss fight.
//
// @Singleton because this is injected at two separate points (LabelResolver and the reset
// hotkey listener, in the main com.groundmarkervariables package) that must share the same
// offset state — Guice hands out a fresh instance per injection point otherwise. Public (unlike
// every other LabelVariable) for the same reason: the hotkey listener outside this package
// needs to call offset().
@Singleton
public class MetronomeLabelVariable implements LabelVariable
{
	// Optional +/- before N forces counting up/down, over both config and party sync.
	private static final Pattern PATTERN = Pattern.compile(
		"\\{(?:metronome|m)([+-]?)(\\d+)(?:_(\\d+))?\\}", Pattern.CASE_INSENSITIVE);

	// Sync target's "Count Down" stops overriding our own config after this many ticks (30s)
	// with no new GMVMetronomeSyncResponse.
	private static final int SYNC_TIMEOUT_TICKS = 50;

	// A new offset only commits after this many consecutive responses agree on it.
	private static final int CONSECUTIVE_REQUIRED = 4;

	private final Client client;
	private final GroundMarkerVariablesConfig config;
	private final PartyService partyService;
	private volatile int offsetTick;
	private volatile boolean syncedCountDown;
	private volatile int lastSyncTick = -SYNC_TIMEOUT_TICKS - 1;
	private volatile int pendingOffset;
	private volatile int pendingCount;

	@Inject
	private MetronomeLabelVariable(Client client, GroundMarkerVariablesConfig config, PartyService partyService)
	{
		this.client = client;
		this.config = config;
		this.partyService = partyService;
	}

	public void offset()
	{
		offsetTick = client.getTickCount();
	}

	// Ticks elapsed since offsetTick — the one value every marker's countdown is derived
	// from, sent to party members as a GMVMetronomeSyncResponse.
	public int elapsedTicks()
	{
		return client.getTickCount() - offsetTick;
	}

	// countDown applies immediately; a new offset needs CONSECUTIVE_REQUIRED matching responses.
	public void syncTo(int remoteElapsedTicks, boolean remoteCountDown)
	{
		lastSyncTick = client.getTickCount();
		syncedCountDown = remoteCountDown;

		int candidateOffset = client.getTickCount() - remoteElapsedTicks;
		if (candidateOffset == offsetTick)
		{
			pendingCount = 0;
			return;
		}

		if (candidateOffset == pendingOffset)
		{
			pendingCount++;
		}
		else
		{
			pendingOffset = candidateOffset;
			pendingCount = 1;
		}

		if (pendingCount >= CONSECUTIVE_REQUIRED)
		{
			offsetTick = pendingOffset;
			pendingCount = 0;
		}
	}

	// The sync target's countDown, unless stale (no response in SYNC_TIMEOUT_TICKS) or we've
	// left the party -- then back to our own config, same as if never synced.
	private boolean effectiveCountDown()
	{
		if (client.getTickCount() - lastSyncTick < SYNC_TIMEOUT_TICKS)
		{
			if (!partyService.isInParty())
			{
				lastSyncTick = -SYNC_TIMEOUT_TICKS;
				pendingCount = 0;
				return config.countDown();
			}

			return syncedCountDown;
		}

		return config.countDown();
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		int max = parseGroup(matcher, 2, -1);
		if (max <= 0)
		{
			return null;
		}

		int ticksPerStep = matcher.group(3) == null ? 1 : parseGroup(matcher, 3, -1);
		if (ticksPerStep <= 0)
		{
			return null;
		}

		String direction = matcher.group(1);
		boolean countDown = direction.isEmpty() ? effectiveCountDown() : direction.equals("-");

		int step = Math.floorDiv(client.getTickCount() - offsetTick, ticksPerStep);
		int position = Math.floorMod(step, max);
		String value = String.valueOf(countDown ? max - position : position + 1);

		if (config.highlightFinalTick() && position == max - 1)
		{
			value = "<col=" + ColorUtil.colorToHexCode(config.finalTickColor()) + ">" + value + "</col>";
		}

		return value;
	}

	// Rich and Plain are identical for {metronomeN[_M]}.
	@Override
	public String resolveRich(Matcher matcher)
	{
		return resolvePlain(matcher);
	}

	// \d+ has no upper bound on digit count, so a marker like {metronome99999999999} can
	// overflow int; fall back to a value the caller treats as invalid rather than crashing.
	private static int parseGroup(Matcher matcher, int group, int onOverflow)
	{
		try
		{
			return Integer.parseInt(matcher.group(group));
		}
		catch (NumberFormatException e)
		{
			return onOverflow;
		}
	}
}

