package com.groundmarkervariables.variables.label;

import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

import com.groundmarkervariables.variables.LabelVariable;
import com.groundmarkervariables.variables.RichText;
import com.groundmarkervariables.variables.support.WorldInfo;
import net.runelite.api.Client;
import net.runelite.api.WorldType;

// {world} / {worldInfo} -> current world number. Rich: "World N (type)"; {worldInfo} adds a
// leading region flag and ": <players> Players | <ping>ms". hideWorld leaves out the number.
public class WorldLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{world(Info(?:\\s*,?\\s*(hideWorld))?)?\\}", Pattern.CASE_INSENSITIVE);

	// Most specific first. Members/skill total worlds show no type.
	private static final List<Map.Entry<WorldType, String>> TYPE_NAMES = List.of(
		Map.entry(WorldType.BETA_WORLD, "Beta"),
		Map.entry(WorldType.TOURNAMENT_WORLD, "Tournament"),
		Map.entry(WorldType.SEASONAL, "Seasonal"),
		Map.entry(WorldType.DEADMAN, "Deadman"),
		Map.entry(WorldType.FRESH_START_WORLD, "Fresh Start"),
		Map.entry(WorldType.HARDCORE_MAIN, "Hardcore"),
		Map.entry(WorldType.LAST_MAN_STANDING, "LMS"),
		Map.entry(WorldType.BOUNTY, "Bounty Hunter"),
		Map.entry(WorldType.PVP_ARENA, "PvP Arena"),
		Map.entry(WorldType.QUEST_SPEEDRUNNING, "Quest"),
		Map.entry(WorldType.NOSAVE_MODE, "No Save"),
		Map.entry(WorldType.HIGH_RISK, "High Risk"),
		Map.entry(WorldType.PVP, "PvP"));

	private final Client client;
	private final WorldInfo worldInfo;
	private final RichText richText;

	@Inject
	private WorldLabelVariable(Client client, WorldInfo worldInfo, RichText richText)
	{
		this.client = client;
		this.worldInfo = worldInfo;
		this.richText = richText;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		return client.getLocalPlayer() == null ? null : String.valueOf(client.getWorld());
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		int world = client.getWorld();
		boolean info = matcher.group(1) != null;
		boolean hideWorld = matcher.group(2) != null;
		StringBuilder sb = new StringBuilder();

		String flag = info ? worldInfo.flagKey(world) : null;
		if (flag != null)
		{
			sb.append("<flag=").append(flag).append("> ");
		}

		String type = typeName(client.getWorldType());
		if (hideWorld)
		{
			// e.g. "Seasonal: 642 Players | 23ms", or just "642 Players | 23ms".
			sb.append(type == null ? "" : type + ": ");
		}
		else
		{
			sb.append("World ").append(richText.highlightValue(String.valueOf(world)));
			if (type != null)
			{
				sb.append(" (").append(type).append(')');
			}
			sb.append(info ? ": " : "");
		}

		if (info)
		{
			Integer players = worldInfo.players(world);
			Integer ping = worldInfo.averagePing();
			sb.append(players == null ? "?" : String.valueOf(players))
				.append(" Players | ")
				.append(ping == null ? richText.animatedDots(client.getTickCount()) : richText.highlightValue(String.valueOf(ping)) + "ms");
		}

		return sb.toString();
	}

	private static String typeName(EnumSet<WorldType> types)
	{
		for (Map.Entry<WorldType, String> entry : TYPE_NAMES)
		{
			if (types.contains(entry.getKey()))
			{
				return entry.getValue();
			}
		}

		return types.contains(WorldType.MEMBERS) ? null : "F2P";
	}
}

package com.groundmarkervariables.variables.label;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

import com.groundmarkervariables.variables.LabelVariable;
import com.groundmarkervariables.variables.RichText;
import com.groundmarkervariables.variables.support.HiscoreRankLookup;
import com.groundmarkervariables.variables.support.SkillFinder;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.client.hiscore.HiscoreSkill;

// {xp_<skill>} -> the player's exact experience in <skill>, e.g. {xp_agility}. Rich Text adds
// the skill's level and hiscore rank, same data as the "!lvl" chat command. Rank comes from
// HiscoreRankLookup -- while it's unavailable (still loading, or genuinely unranked), shown as
// animated dots, since the two cases can't be told apart from its API.
public class XpLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{xp_([a-z]+)\\}", Pattern.CASE_INSENSITIVE);

	private final Client client;
	private final RichText richText;
	private final HiscoreRankLookup rankLookup;

	@Inject
	private XpLabelVariable(Client client, RichText richText, HiscoreRankLookup rankLookup)
	{
		this.client = client;
		this.richText = richText;
		this.rankLookup = rankLookup;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		Skill skill = SkillFinder.find(matcher.group(1));
		if (skill == null || client.getLocalPlayer() == null)
		{
			return null;
		}

		return String.valueOf(client.getSkillExperience(skill));
	}

	@Override
	public String resolveRich(Matcher matcher)
	{
		Skill skill = SkillFinder.find(matcher.group(1));
		if (skill == null || client.getLocalPlayer() == null)
		{
			return null;
		}

		Long rank = rankLookup.rank(HiscoreSkill.valueOf(skill.name()));
		String rankText = rank == null ? richText.animatedDots(client.getTickCount()) : richText.highlightValue(String.format("%,d", rank));

		return skill.getName() + " Level: " + richText.highlightValue(String.valueOf(client.getRealSkillLevel(skill)))
			+ " | Experience: " + richText.highlightValue(String.format("%,d", client.getSkillExperience(skill)))
			+ " | Rank: " + rankText;
	}
}

package com.groundmarkervariables.variables.label;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

import com.groundmarkervariables.variables.LabelVariable;
import com.groundmarkervariables.variables.RichText;
import com.groundmarkervariables.variables.support.SkillFinder;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.xptracker.XpTrackerPlugin;
import net.runelite.client.plugins.xptracker.XpTrackerService;

// {xpRate_<skill>} -> the player's current xp/hour in <skill> from the XP Tracker plugin, e.g.
// {xpRate_agility}, {xpRate_fishing}. <skill> matches any Skill.getName() case-insensitively,
// same as {lvl_<skill>}/{boost_<skill>}. Resolves to "N/A" if XP Tracker isn't running, since
// its numbers are otherwise meaninglessly 0.
public class XpRateLabelVariable implements LabelVariable
{
	private static final Pattern PATTERN = Pattern.compile("\\{xpRate_([a-z]+)\\}", Pattern.CASE_INSENSITIVE);
	private static final String XP_TRACKER_DISABLED_TEXT = "N/A";
	private static final String XP_TRACKER_DISABLED_RICH_TEXT = "Enable XP Tracker Plugin";
	private static final int ABBREVIATE_ABOVE = 10_000;

	private final Client client;
	private final XpTrackerService xpTrackerService;
	private final PluginManager pluginManager;
	private final RichText richText;

	@Inject
	private XpRateLabelVariable(Client client, XpTrackerService xpTrackerService, PluginManager pluginManager,
		RichText richText)
	{
		this.client = client;
		this.xpTrackerService = xpTrackerService;
		this.pluginManager = pluginManager;
		this.richText = richText;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public String resolvePlain(Matcher matcher)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		Skill skill = SkillFinder.find(matcher.group(1));
		if (skill == null)
		{
			return null;
		}

		return isXpTrackerRunning() ? String.valueOf(xpTrackerService.getXpHr(skill)) : XP_TRACKER_DISABLED_TEXT;
	}

	// Needs the raw int for k-formatting, and diverges from Plain when disabled, so this
	// doesn't delegate to resolvePlain.
	@Override
	public String resolveRich(Matcher matcher)
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		Skill skill = SkillFinder.find(matcher.group(1));
		if (skill == null)
		{
			return null;
		}

		if (!isXpTrackerRunning())
		{
			return XP_TRACKER_DISABLED_RICH_TEXT;
		}

		return richText.labeled(skill.getName() + " XP/hr", formatXpHr(xpTrackerService.getXpHr(skill)));
	}

	// > 10,000 abbreviates to the nearest thousand ("48k"); at or below, shows the exact number.
	private static String formatXpHr(int xpHr)
	{
		return xpHr > ABBREVIATE_ABOVE ? (xpHr / 1000) + "k" : String.valueOf(xpHr);
	}

	private boolean isXpTrackerRunning()
	{
		return pluginManager.getPlugins().stream()
			.anyMatch(plugin -> plugin.getClass() == XpTrackerPlugin.class && pluginManager.isPluginActive(plugin));
	}
}

