package com.groundmarkervariables.variables.meta;

import java.awt.Color;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

import com.groundmarkervariables.GroundMarkerVariablesConfig;
import com.groundmarkervariables.variables.support.NamedColors;
import net.runelite.client.util.ColorUtil;

// {highlight<corner>} / {highlight<corner>=<col>} -- SW/NW/NE/SE, or Corners/All for all four.
public class HighlightMetaVariable implements MetaVariable
{
	private static final Pattern PATTERN = Pattern.compile(
		"\\{highlight(SW|NW|NE|SE|Corners|All)(?:=(" + String.join("|", NamedColors.HEX_BY_NAME.keySet())
			+ "|" + String.join("|", NamedColors.OPACITY_BY_NAME.keySet()) + "))?\\}",
		Pattern.CASE_INSENSITIVE);

	private final GroundMarkerVariablesConfig config;

	@Inject
	private HighlightMetaVariable(GroundMarkerVariablesConfig config)
	{
		this.config = config;
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public void apply(Matcher matcher, MetaState state)
	{
		Color color = resolveColor(matcher.group(2));
		for (HighlightCorner corner : corners(matcher.group(1)))
		{
			state.setHighlight(corner, color);
		}
	}

	private Color resolveColor(String value)
	{
		if (value == null)
		{
			return config.highlightColor();
		}

		Integer opacity = NamedColors.OPACITY_BY_NAME.get(value.toLowerCase(Locale.ROOT));
		if (opacity != null)
		{
			return ColorUtil.colorWithAlpha(config.highlightColor(), Math.round(opacity / 100f * 255));
		}

		return new Color(Integer.parseInt(NamedColors.HEX_BY_NAME.get(value.toLowerCase(Locale.ROOT)), 16));
	}

	private static List<HighlightCorner> corners(String arg)
	{
		if ("corners".equalsIgnoreCase(arg) || "all".equalsIgnoreCase(arg))
		{
			return List.of(HighlightCorner.values());
		}

		return List.of(HighlightCorner.valueOf(arg.toUpperCase(Locale.ROOT)));
	}
}

package com.groundmarkervariables.variables.meta;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

// {align=left/right/center} / {/align} -- scoped from the line it's on through the next
// {align}/{/align} (which resets to center), so it's handled separately from MetaVariable.
final class LineAlignment
{
	private static final Pattern TOKEN = Pattern.compile("\\{align=(left|right|center)\\}|\\{/align\\}", Pattern.CASE_INSENSITIVE);

	private LineAlignment()
	{
	}

	static final class Result
	{
		final String label;
		final List<TextAlign> lineAlignments;

		private Result(String label, List<TextAlign> lineAlignments)
		{
			this.label = label;
			this.lineAlignments = lineAlignments;
		}
	}

	static Result strip(String label)
	{
		String[] rawLines = label.split("\\\\n", -1);
		List<String> strippedLines = new ArrayList<>();
		List<TextAlign> alignments = new ArrayList<>();
		TextAlign current = TextAlign.CENTER;

		for (String line : rawLines)
		{
			Matcher matcher = TOKEN.matcher(line);
			StringBuilder stripped = new StringBuilder();
			int last = 0;
			while (matcher.find())
			{
				stripped.append(line, last, matcher.start());
				last = matcher.end();
				current = matcher.group(1) == null ? TextAlign.CENTER : TextAlign.valueOf(matcher.group(1).toUpperCase(Locale.ROOT));
			}
			stripped.append(line.substring(last));

			strippedLines.add(stripped.toString());
			alignments.add(current);
		}

		// Trailing lines left empty by stripping (e.g. a final "{/align}" on its own line)
		// would otherwise render as blank rows.
		int lastIndex = strippedLines.size() - 1;
		while (lastIndex >= 0 && strippedLines.get(lastIndex).isEmpty())
		{
			strippedLines.remove(lastIndex);
			alignments.remove(lastIndex);
			lastIndex--;
		}

		return new Result(String.join("\\n", strippedLines), alignments);
	}
}

