package com.groundmarkervariables.variables.meta;

import java.awt.Color;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

import com.groundmarkervariables.variables.support.NamedColors;

// {tileCol=<col>} -- <col> is a hex/named color (RRGGBB, same as <col=...>), an 8-digit hex
// with a leading alpha byte (AARRGGBB), "N%", or an opacity name (invis/opaque/solid) to keep
// the tile's own color at that opacity.
public class TileColMetaVariable implements MetaVariable
{
	private static final Pattern PATTERN = Pattern.compile(
		"\\{tileCol=(\\d{1,3}%|[0-9a-fA-F]{6}|[0-9a-fA-F]{8}|"
			+ String.join("|", NamedColors.HEX_BY_NAME.keySet()) + "|" + String.join("|", NamedColors.OPACITY_BY_NAME.keySet()) + ")\\}",
		Pattern.CASE_INSENSITIVE);

	@Inject
	private TileColMetaVariable()
	{
	}

	@Override
	public Pattern pattern()
	{
		return PATTERN;
	}

	@Override
	public void apply(Matcher matcher, MetaState state)
	{
		String value = matcher.group(1);
		Integer opacityName = NamedColors.OPACITY_BY_NAME.get(value.toLowerCase(Locale.ROOT));
		if (opacityName != null)
		{
			state.setTileOpacity(opacityName / 100f);
			return;
		}

		if (value.endsWith("%"))
		{
			float percent = Math.max(0, Math.min(100, Float.parseFloat(value.substring(0, value.length() - 1))));
			state.setTileOpacity(percent / 100f);
			return;
		}

		String hex = NamedColors.HEX_BY_NAME.getOrDefault(value.toLowerCase(Locale.ROOT), value);
		if (hex.length() == 8)
		{
			state.setTileOpacity(Integer.parseInt(hex.substring(0, 2), 16) / 255f);
			hex = hex.substring(2);
		}

		state.setTileColor(new Color(Integer.parseInt(hex, 16)));
	}
}

package com.groundmarkervariables.variables.support;

import java.util.Map;

import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;

// Matches a canonical boss name (as BossAliases.resolve() returns) to its HiscoreSkill entry --
// same "no 'The ' prefix, no colon" transform AdvancedLabelEditor's own autocomplete uses.
public final class BossHiscoreSkill
{
	// Lunar Chest's kc message is singular; the hiscores entry is plural.
	private static final Map<String, String> NAME_OVERRIDES = Map.of("Lunar Chest", "Lunar Chests");

	private BossHiscoreSkill()
	{
	}

	public static HiscoreSkill find(String canonicalName)
	{
		canonicalName = NAME_OVERRIDES.getOrDefault(canonicalName, canonicalName);
		for (HiscoreSkill skill : HiscoreSkill.values())
		{
			if (skill.getType() != HiscoreSkillType.BOSS)
			{
				continue;
			}

			String name = skill.getName();
			if (name.regionMatches(true, 0, "The ", 0, 4))
			{
				name = name.substring(4);
			}
			name = name.replace(":", "");

			if (name.equalsIgnoreCase(canonicalName))
			{
				return skill;
			}
		}

		return null;
	}
}

package com.groundmarkervariables.variables.support;

import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

// Tracks per-boss kill counts for {kc <boss>}, learned from the same game-message text and
// regex Chat Commands' own KILLCOUNT_PATTERN uses (ChatCommandsPlugin#onChatMessage) — kept
// independent of that plugin (it might be disabled) rather than depending on it, but getKc()
// still falls back to reading its stored "killcount" RS-profile data (read-only) so {kc}
// already has a value on a fresh install if Chat Commands has ever seen the kill.
//
// @Singleton for the same reason as MetronomeLabelVariable: injected both here (as a
// LabelVariable, via VariableRegistry) and in GroundMarkerVariablesPlugin#onChatMessage, which
// must share the one tracker instance. Public for the same cross-package-access reason.
@Singleton
public class BossKillCountTracker
{
	private static final String GROUP = "groundMarkerVariablesKc";
	private static final String CHAT_COMMANDS_GROUP = "killcount";

	// Ported from ChatCommandsPlugin.KILLCOUNT_PATTERN — matches messages like "Your Zulrah
	// kill count is: 50.", "Your Chambers of Xeric count is: 5.", "Your subdued Wintertodt
	// count is: 12.", "Your Theatre of Blood completion count is: 3." etc.
	private static final Pattern KILLCOUNT_PATTERN = Pattern.compile(
		"Your (?<pre>completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?(?<boss>.+?)(?:</col>)? "
			+ "(?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?)is: ?"
			+ "(?:<col=[0-9a-f]{6}>|@.+?@)(?<kc>[0-9,]+)</col>");

	private static final Map<String, String> KILLCOUNT_RENAMES = Map.of("Barrows chest", "Barrows Chests");

	private final ConfigManager configManager;

	@Inject
	private BossKillCountTracker(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	public void onChatMessage(String message)
	{
		Matcher matcher = KILLCOUNT_PATTERN.matcher(message);
		if (!matcher.find())
		{
			return;
		}

		String boss = matcher.group("boss");
		int kc;
		try
		{
			kc = Integer.parseInt(matcher.group("kc").replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return;
		}

		// Neither qualifying word present means this isn't really a kill-count line (e.g. some
		// unrelated "Your ... is: <number>" message) — same false-positive guard as the source.
		if (isEmpty(matcher.group("pre")) && isEmpty(matcher.group("post")))
		{
			return;
		}

		String renamedBoss = KILLCOUNT_RENAMES.getOrDefault(boss, boss).replace(":", "");
		configManager.setRSProfileConfiguration(GROUP, renamedBoss.toLowerCase(Locale.ENGLISH), kc);
	}

	public Integer getKc(String boss)
	{
		String key = boss.toLowerCase(Locale.ENGLISH);
		Integer own = configManager.getRSProfileConfiguration(GROUP, key, int.class);
		if (own != null)
		{
			return own;
		}

		return configManager.getRSProfileConfiguration(CHAT_COMMANDS_GROUP, key, int.class);
	}

	private static boolean isEmpty(String value)
	{
		return value == null || value.isEmpty();
	}
}

package com.groundmarkervariables.variables.support;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

// Boss NPC id -> name with its fight stage, e.g. "Phantom Muspah (Ranged)", for {dps bossReport}.
// Downloaded once from this plugin's GitHub repo; data/bosses.json is made by scripts/build-bosses.py.
@Slf4j
@Singleton
public class BossNames
{
	private static final HttpUrl URL = HttpUrl.get("https://raw.githubusercontent.com/Limy-Monkey/Ground-Marker-Variables/master/data/bosses.json");
	private static final Type TYPE = new TypeToken<Map<Integer, Boss>>()
	{
	}.getType();

	private static final class Boss
	{
		private String name;
	}

	private final OkHttpClient okHttpClient;
	private final Gson gson;

	private volatile Map<Integer, Boss> bosses = Map.of();
	private volatile boolean requested;

	@Inject
	private BossNames(OkHttpClient okHttpClient, Gson gson)
	{
		this.okHttpClient = okHttpClient;
		this.gson = gson;
	}

	// Once, unless it failed: then again on the next call.
	public void load()
	{
		if (requested)
		{
			return;
		}
		requested = true;

		okHttpClient.newCall(new Request.Builder().url(URL).build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Couldn't download boss names", e);
				requested = false;
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						log.warn("Couldn't download boss names: HTTP {}", response.code());
						requested = false;
						return;
					}

					Map<Integer, Boss> loaded = gson.fromJson(body.charStream(), TYPE);
					bosses = loaded == null ? Map.of() : loaded;
				}
				catch (JsonParseException e)
				{
					log.warn("Couldn't read boss names", e);
				}
			}
		});
	}

	// Null if it isn't a boss, or the list hasn't downloaded.
	@Nullable
	public String name(int npcId)
	{
		Boss boss = bosses.get(npcId);
		return boss == null ? null : boss.name;
	}
}

package com.groundmarkervariables.variables.support;

import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.StructComposition;

// Every collection log item, from the client's own cache. Built on first use (client thread only).
@Singleton
public class CollectionLog
{
	private static final int TABS_ENUM = 2102;
	private static final int TAB_PAGES_PARAM = 683;
	private static final int PAGE_NAME_PARAM = 689;
	private static final int PAGE_ITEMS_PARAM = 690;
	private static final String ALL_PETS_PAGE = "All Pets";

	private final Client client;

	private Set<Integer> items;
	private Set<Integer> pets;

	@Inject
	private CollectionLog(Client client)
	{
		this.client = client;
	}

	public boolean contains(int itemId)
	{
		load();
		return items.contains(itemId);
	}

	public boolean isPet(int itemId)
	{
		load();
		return pets.contains(itemId);
	}

	private void load()
	{
		if (items != null)
		{
			return;
		}

		Set<Integer> allItems = new HashSet<>();
		Set<Integer> allPets = new HashSet<>();
		for (int tabStruct : client.getEnum(TABS_ENUM).getIntVals())
		{
			int pagesEnum = client.getStructComposition(tabStruct).getIntValue(TAB_PAGES_PARAM);
			for (int pageStruct : client.getEnum(pagesEnum).getIntVals())
			{
				StructComposition page = client.getStructComposition(pageStruct);
				boolean petsPage = ALL_PETS_PAGE.equals(page.getStringValue(PAGE_NAME_PARAM));
				for (int itemId : client.getEnum(page.getIntValue(PAGE_ITEMS_PARAM)).getIntVals())
				{
					allItems.add(itemId);
					if (petsPage)
					{
						allPets.add(itemId);
					}
				}
			}
		}

		items = allItems;
		pets = allPets;
	}
}

package com.groundmarkervariables.variables.support;

import java.text.ParseException;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeFormatterBuilder;
import java.time.format.DateTimeParseException;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;

import com.groundmarkervariables.variables.LabelVariable;
import com.groundmarkervariables.variables.label.MathVariable;
import com.groundmarkervariables.variables.label.SixHourTimeRemainingLabelVariable;
import com.groundmarkervariables.variables.VariableRegistry;
import net.runelite.client.util.QuantityFormatter;

// Shared <expr> [<cmp> <value>] evaluation for ConditionalVariable and BooleanVariable. <expr>
// is resolved by re-wrapping it in braces and testing it against every VariableRegistry
// variable's own pattern(), so this works for any variable without changes here. == and != are
// always case-insensitive string equality; ordering comparators need both sides to parse as
// numbers, or failing that as a clock time (see tryParseTime).
public class ConditionEvaluator
{
	// "9pm"/"9:00pm" (am/pm required) or "21:00"/"9:00" (24-hour, no marker) — tryParseTime
	// strips spaces/periods first so "3:45 pm" (as {time} itself renders) also matches.
	private static final DateTimeFormatter TIME_WITH_AMPM =
		new DateTimeFormatterBuilder().parseCaseInsensitive().appendPattern("h[:mm]a").toFormatter(Locale.ENGLISH);
	private static final DateTimeFormatter TIME_24_HOUR =
		new DateTimeFormatterBuilder().parseCaseInsensitive().appendPattern("H[:mm]").toFormatter(Locale.ENGLISH);

	// See parseHoursThreshold().
	private static final Pattern HOURS_PATTERN = Pattern.compile("(-?\\d+(?:\\.\\d+)?)\\s*(?:hours?|hrs?)?", Pattern.CASE_INSENSITIVE);
	private static final Pattern HOURS_MINUTES_PATTERN = Pattern.compile("(-?\\d+):(\\d{1,2})");

	private final List<LabelVariable> variables;
	private final SixHourTimeRemainingLabelVariable sixHourTimeRemaining;
	private final MathVariable mathVariable;

	@Inject
	private ConditionEvaluator(VariableRegistry registry, SixHourTimeRemainingLabelVariable sixHourTimeRemaining, MathVariable mathVariable)
	{
		this.variables = registry.all();
		this.sixHourTimeRemaining = sixHourTimeRemaining;
		this.mathVariable = mathVariable;
	}

	// <expr>'s own Plain Text value, or null if <expr> doesn't match any base variable.
	// MathVariable isn't itself in VariableRegistry (it depends on NumericVariableRegistry
	// instead, to avoid a circular dependency back through here), so it's tried directly.
	public String resolveExpression(String expr)
	{
		Matcher mathMatcher = mathVariable.pattern().matcher("{" + expr + "}");
		if (mathMatcher.matches())
		{
			return mathVariable.resolvePlain(mathMatcher);
		}

		for (LabelVariable variable : variables)
		{
			Matcher wrapped = variable.pattern().matcher("{" + expr + "}");
			if (wrapped.matches())
			{
				return variable.resolvePlain(wrapped); // always Plain — see callers' comments
			}
		}

		return null;
	}

	public Boolean evaluateCondition(String expr, String comparator, String expected)
	{
		if (comparator != null && isSixHourTimeRemaining(expr))
		{
			return evaluateSixHourWarning(comparator, expected);
		}

		String actual = resolveExpression(expr);
		return actual == null ? null : evaluate(actual, comparator, expected);
	}

	// Shared with BooleanVariable, which also needs to know this for its own </<= restriction
	// and duration-specific Rich/Plain text.
	public boolean isSixHourTimeRemaining(String expr)
	{
		return sixHourTimeRemaining.pattern().matcher("{" + expr.trim() + "}").matches();
	}

	// {6HourTimeRemaining}'s own Plain Text is an "h:mm" duration string -- comparing that
	// against <hours> the normal way would misparse both as clock times.
	private Boolean evaluateSixHourWarning(String comparator, String expected)
	{
		Double threshold = parseHoursThreshold(expected.trim());
		if (threshold == null)
		{
			return null;
		}

		double hoursRemaining = sixHourTimeRemaining.remaining().toMinutes() / 60.0;
		return evaluate(String.valueOf(hoursRemaining), comparator, String.valueOf(threshold));
	}

	// <hours> is either a bare number, optionally suffixed with "hour(s)"/"hr(s)" (e.g. "1.5
	// hours", "1.5hrs"), or "h:mm" matching {6HourTimeRemaining}'s own Plain Text (e.g. "5:45").
	private static Double parseHoursThreshold(String value)
	{
		Matcher hoursMatcher = HOURS_PATTERN.matcher(value);
		if (hoursMatcher.matches())
		{
			return Double.parseDouble(hoursMatcher.group(1));
		}

		Matcher hoursMinutesMatcher = HOURS_MINUTES_PATTERN.matcher(value);
		if (hoursMinutesMatcher.matches())
		{
			return Integer.parseInt(hoursMinutesMatcher.group(1)) + Integer.parseInt(hoursMinutesMatcher.group(2)) / 60.0;
		}

		return null;
	}

	// Null means "can't be evaluated" (e.g. an ordering comparator against a non-numeric
	// value like a player name), distinct from false, so callers can leave things untouched
	// rather than silently picking a result for an unanswerable check.
	public Boolean evaluate(String actual, String comparator, String expected)
	{
		if (comparator == null)
		{
			return tryParseBoolean(actual);
		}

		String resolvedExpected = resolveExpression(expected);
		if (resolvedExpected != null)
		{
			expected = resolvedExpected;
		}

		if ("==".equals(comparator))
		{
			return actual.equalsIgnoreCase(expected);
		}

		if ("!=".equals(comparator))
		{
			return !actual.equalsIgnoreCase(expected);
		}

		Double actualNum = tryParseNumber(actual);
		Double expectedNum = tryParseNumber(expected);
		if (actualNum != null && expectedNum != null)
		{
			return compareOrder(comparator, actualNum, expectedNum);
		}

		LocalTime actualTime = tryParseTime(actual);
		LocalTime expectedTime = tryParseTime(expected);
		if (actualTime != null && expectedTime != null)
		{
			return compareOrder(comparator, actualTime.toSecondOfDay(), expectedTime.toSecondOfDay());
		}

		return null;
	}

	private static Boolean compareOrder(String comparator, double actual, double expected)
	{
		switch (comparator)
		{
			case "<":
				return actual < expected;
			case ">":
				return actual > expected;
			case "<=":
				return actual <= expected;
			case ">=":
				return actual >= expected;
			default:
				return null;
		}
	}

	public static LocalTime tryParseTime(String value)
	{
		String normalized = value.trim().toLowerCase(Locale.ENGLISH).replace(".", "").replaceAll("\\s+", "");
		if (normalized.isEmpty())
		{
			return null;
		}

		try
		{
			return LocalTime.parse(normalized, TIME_WITH_AMPM);
		}
		catch (DateTimeParseException e)
		{
			// Not "9pm"-shaped — fall through and try it as a bare 24-hour time instead.
		}

		try
		{
			return LocalTime.parse(normalized, TIME_24_HOUR);
		}
		catch (DateTimeParseException e)
		{
			return null;
		}
	}

	// Falls back to RuneLite's own K/M/B stack-size suffix, e.g. "10.5k" -> 10500, so
	// {loot monster > 10.5k} works the same way {loot}'s own Rich Text displays gp.
	public static Double tryParseNumber(String value)
	{
		try
		{
			return Double.parseDouble(value);
		}
		catch (NumberFormatException e)
		{
			// Not a bare number — fall through and try it as a suffixed stack size instead.
		}

		try
		{
			return (double) QuantityFormatter.parseQuantity(value);
		}
		catch (ParseException e)
		{
			return null;
		}
	}

	// Strict on purpose: a non-boolean variable used bare (e.g. {spellbook ? A : B}) should
	// be unresolvable, not silently treated as false.
	private static Boolean tryParseBoolean(String value)
	{
		if ("true".equalsIgnoreCase(value))
		{
			return Boolean.TRUE;
		}

		if ("false".equalsIgnoreCase(value))
		{
			return Boolean.FALSE;
		}

		return null;
	}
}

package com.groundmarkervariables.variables.support;

import java.time.DateTimeException;
import java.time.LocalDate;
import java.time.chrono.Chronology;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeFormatterBuilder;
import java.time.format.DateTimeParseException;
import java.time.format.FormatStyle;
import java.time.temporal.ChronoField;
import java.time.temporal.TemporalAccessor;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

// Parses a bare date literal for MathVariable's date countdown -- "Oct 20"/"October 20",
// optionally with an explicit year, or slash/dash numeric ("10/20", "10-20-2026") using the
// system locale's own day/month order. No year specified always means the current year.
public final class DateLiteralParser
{
	private static final DateTimeFormatter[] MONTH_DAY_FORMATS = {
		caseInsensitive("MMM d"),
		caseInsensitive("MMMM d"),
	};
	private static final DateTimeFormatter[] MONTH_DAY_YEAR_FORMATS = {
		caseInsensitive("MMM d yyyy"),
		caseInsensitive("MMMM d yyyy"),
	};
	private static final Pattern NUMERIC_DATE = Pattern.compile("(\\d{1,2})[/-](\\d{1,2})(?:[/-](\\d{4}))?");

	private DateLiteralParser()
	{
	}

	private static DateTimeFormatter caseInsensitive(String pattern)
	{
		return new DateTimeFormatterBuilder().parseCaseInsensitive().appendPattern(pattern).toFormatter(Locale.ENGLISH);
	}

	public static LocalDate parse(String text)
	{
		String trimmed = text.trim().replace(",", "");

		LocalDate date = parseWithFormats(trimmed, MONTH_DAY_YEAR_FORMATS);
		if (date != null)
		{
			return date;
		}

		date = parseMonthDay(trimmed);
		if (date != null)
		{
			return date;
		}

		return parseNumeric(trimmed);
	}

	private static LocalDate parseWithFormats(String text, DateTimeFormatter[] formats)
	{
		for (DateTimeFormatter format : formats)
		{
			try
			{
				return LocalDate.parse(text, format);
			}
			catch (DateTimeParseException e)
			{
				// Try the next format.
			}
		}
		return null;
	}

	// "MMM d"/"MMMM d" alone can't parse to a LocalDate (no year) -- read the fields back out
	// and combine with the current year instead.
	private static LocalDate parseMonthDay(String text)
	{
		for (DateTimeFormatter format : MONTH_DAY_FORMATS)
		{
			try
			{
				TemporalAccessor parsed = format.parse(text);
				return LocalDate.of(LocalDate.now().getYear(),
					parsed.get(ChronoField.MONTH_OF_YEAR), parsed.get(ChronoField.DAY_OF_MONTH));
			}
			catch (DateTimeException e)
			{
				// Try the next format.
			}
		}
		return null;
	}

	private static LocalDate parseNumeric(String text)
	{
		Matcher matcher = NUMERIC_DATE.matcher(text);
		if (!matcher.matches())
		{
			return null;
		}

		int first = Integer.parseInt(matcher.group(1));
		int second = Integer.parseInt(matcher.group(2));
		boolean dayFirst = isDayFirstLocale();
		int month = dayFirst ? second : first;
		int day = dayFirst ? first : second;
		int year = matcher.group(3) != null ? Integer.parseInt(matcher.group(3)) : LocalDate.now().getYear();

		try
		{
			return LocalDate.of(year, month, day);
		}
		catch (DateTimeException e)
		{
			return null;
		}
	}

	private static boolean isDayFirstLocale()
	{
		Locale locale = Locale.getDefault();
		String pattern = DateTimeFormatterBuilder.getLocalizedDateTimePattern(
			FormatStyle.SHORT, null, Chronology.ofLocale(locale), locale);
		int dayIndex = pattern.indexOf('d');
		int monthIndex = pattern.indexOf('M');
		return dayIndex >= 0 && monthIndex >= 0 && dayIndex < monthIndex;
	}
}

